-- Settled non-trade cash transactions; ordinary journals and all existing close guards remain authoritative.
CREATE TABLE accounting.bank_transactions(id uuid PRIMARY KEY,company_id uuid NOT NULL REFERENCES core.companies(id),kind text NOT NULL CHECK(kind IN('RECEIVE','PAY','TRANSFER')),bank_account_id uuid NOT NULL,counter_bank_account_id uuid,occurred_on date NOT NULL,reference text NOT NULL CHECK(length(btrim(reference))BETWEEN 1 AND 200),reason text NOT NULL CHECK(length(btrim(reason))BETWEEN 1 AND 2000),gst_basis text NOT NULL CHECK(gst_basis IN('CASH','NON_CASH')),gst_registered boolean NOT NULL,gross numeric(20,2)NOT NULL CHECK(gross>0),journal_entry_id uuid NOT NULL,statement_line_id uuid,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES identity.users(id),UNIQUE(company_id,id),UNIQUE(company_id,reference),UNIQUE(company_id,journal_entry_id),FOREIGN KEY(company_id,id)REFERENCES platform.documents(company_id,id),FOREIGN KEY(company_id,bank_account_id)REFERENCES accounting.bank_accounts(company_id,id),FOREIGN KEY(company_id,counter_bank_account_id)REFERENCES accounting.bank_accounts(company_id,id),FOREIGN KEY(company_id,journal_entry_id)REFERENCES accounting.journal_entries(company_id,id)DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(company_id,statement_line_id)REFERENCES accounting.bank_statement_lines(company_id,id),CHECK((kind='TRANSFER')=(counter_bank_account_id IS NOT NULL)),CHECK(counter_bank_account_id IS NULL OR counter_bank_account_id<>bank_account_id));
CREATE TABLE accounting.bank_transaction_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES core.companies(id),transaction_id uuid NOT NULL,line_no int NOT NULL CHECK(line_no>0),account_id uuid NOT NULL,description text NOT NULL CHECK(length(btrim(description))BETWEEN 1 AND 500),net numeric(20,2)NOT NULL CHECK(net>0),tax numeric(20,2)NOT NULL CHECK(tax>=0),recoverable_tax numeric(20,2)NOT NULL CHECK(recoverable_tax>=0 AND recoverable_tax<=tax),tax_code_id uuid NOT NULL,tax_category text NOT NULL,tax_rate numeric NOT NULL,tax_account_id uuid,bas_class text NOT NULL CHECK(bas_class IN('TAXABLE','EXPORT','OTHER_GST_FREE','INPUT_TAXED','CAPITAL','NON_CAPITAL','EXCLUDED')),input_taxed_percent numeric NOT NULL CHECK(input_taxed_percent BETWEEN 0 AND 100 AND input_taxed_percent=round(input_taxed_percent,4)),cash_flow_category text NOT NULL CHECK(cash_flow_category IN('OPERATING','INVESTING','FINANCING')),snapshot jsonb NOT NULL,UNIQUE(company_id,id),UNIQUE(company_id,transaction_id,line_no),FOREIGN KEY(company_id,transaction_id)REFERENCES accounting.bank_transactions(company_id,id),FOREIGN KEY(company_id,account_id)REFERENCES accounting.accounts(company_id,id),FOREIGN KEY(company_id,tax_code_id)REFERENCES accounting.tax_codes(company_id,id),FOREIGN KEY(company_id,tax_account_id)REFERENCES accounting.accounts(company_id,id));
CREATE TABLE accounting.bank_transaction_reversals(id uuid PRIMARY KEY,company_id uuid NOT NULL REFERENCES core.companies(id),original_id uuid NOT NULL,reference text NOT NULL CHECK(length(btrim(reference))BETWEEN 1 AND 200),reason text NOT NULL CHECK(length(btrim(reason))BETWEEN 1 AND 2000),journal_entry_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES identity.users(id),UNIQUE(company_id,id),UNIQUE(company_id,original_id),UNIQUE(company_id,reference),UNIQUE(company_id,journal_entry_id),FOREIGN KEY(company_id,id)REFERENCES platform.documents(company_id,id),FOREIGN KEY(company_id,original_id)REFERENCES accounting.bank_transactions(company_id,id),FOREIGN KEY(company_id,journal_entry_id)REFERENCES accounting.journal_entries(company_id,id)DEFERRABLE INITIALLY DEFERRED);
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['bank_transactions','bank_transaction_lines','bank_transaction_reversals']LOOP EXECUTE format('ALTER TABLE accounting.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE accounting.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY company_scope ON accounting.%I USING(company_id=core.current_company())WITH CHECK(company_id=core.current_company())',t);EXECUTE format('CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON accounting.%I FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation()',t);EXECUTE format('CREATE TRIGGER bas_dirty BEFORE INSERT OR UPDATE OR DELETE ON accounting.%I FOR EACH STATEMENT EXECUTE FUNCTION accounting.bas_dirty()',t);EXECUTE format('CREATE TRIGGER bas_lock BEFORE INSERT OR UPDATE OR DELETE ON accounting.%I FOR EACH ROW EXECUTE FUNCTION accounting.bas_write_lock()',t);EXECUTE format('CREATE CONSTRAINT TRIGGER bas_frozen AFTER INSERT OR UPDATE OR DELETE ON accounting.%I DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION accounting.bas_check_frozen()',t);EXECUTE format('CREATE CONSTRAINT TRIGGER accounting_frozen AFTER INSERT OR UPDATE OR DELETE ON accounting.%I DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION accounting.check_closed_periods()',t);END LOOP;END $$;
INSERT INTO identity.permissions(code,description)VALUES('accounting.bank_transactions.read','Read non-trade cash source documents'),('accounting.bank_transactions.post','Post settled general income or expense'),('accounting.bank_transactions.transfer','Post atomic same-company AUD account transfer'),('accounting.bank_transactions.classify','Create and match a statement classification atomically'),('accounting.bank_transactions.reverse','Reverse a non-trade cash transaction on its original date');
CREATE FUNCTION identity.seed_general_banking_roles(c uuid)RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN INSERT INTO accounting.tax_codes(company_id,code,name,category)VALUES(c,'INP-BANK','Input-taxed bank income','INPUT_TAXED')ON CONFLICT(company_id,code)DO NOTHING;INSERT INTO accounting.tax_rates(company_id,tax_code_id,rate,effective_from)SELECT c,t.id,0,'2000-07-01'FROM accounting.tax_codes t WHERE t.company_id=c AND t.code='INP-BANK'AND t.category='INPUT_TAXED'AND NOT EXISTS(SELECT 1 FROM accounting.tax_rates r WHERE r.company_id=c AND r.tax_code_id=t.id); INSERT INTO identity.role_permissions(company_id,role_id,permission_code)SELECT c,r.id,p.code FROM identity.roles r CROSS JOIN identity.permissions p WHERE r.company_id=c AND r.code IN('ADMIN','FINANCE')AND p.code LIKE'accounting.bank_transactions.%'ON CONFLICT DO NOTHING;END $$;
DO $$DECLARE c uuid;BEGIN FOR c IN SELECT id FROM core.companies LOOP PERFORM set_config('htt.company_id',c::text,true);PERFORM identity.seed_general_banking_roles(c);SET CONSTRAINTS ALL IMMEDIATE;SET CONSTRAINTS ALL DEFERRED;END LOOP;PERFORM set_config('htt.company_id','',true);END $$;
CREATE FUNCTION accounting.require_general_banking(p_cap text)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN
 PERFORM purchase.require_access('accounting.bank_transactions.read');PERFORM purchase.require_access('accounting.banks.read');PERFORM purchase.require_access('accounting.ledger.read');PERFORM purchase.require_access('accounting.gst.read');PERFORM purchase.require_access('purchase.input_gst.read');
 IF p_cap<>'accounting.bank_transactions.read'THEN PERFORM purchase.require_access(p_cap);PERFORM purchase.require_access('accounting.banks.use');PERFORM purchase.require_access('accounting.cash_flow.classify');PERFORM purchase.require_access('accounting.reports.read');END IF;END $$;
CREATE VIEW accounting.bank_transaction_events WITH(security_invoker=true)AS
 SELECT h.company_id,h.id AS source_document_id,l.id AS source_id,h.id AS original_id,h.kind,h.bank_account_id,h.occurred_on AS event_date,h.gst_basis,h.gst_registered,l.tax_code_id,l.tax_category,l.tax_account_id,l.bas_class,l.input_taxed_percent,l.net,l.tax,l.recoverable_tax,l.snapshot,false AS is_reversal FROM accounting.bank_transactions h JOIN accounting.bank_transaction_lines l ON l.company_id=h.company_id AND l.transaction_id=h.id
 UNION ALL SELECT h.company_id,v.id,l.id,h.id,h.kind,h.bank_account_id,h.occurred_on,h.gst_basis,h.gst_registered,l.tax_code_id,l.tax_category,l.tax_account_id,l.bas_class,l.input_taxed_percent,-l.net,-l.tax,-l.recoverable_tax,l.snapshot,true FROM accounting.bank_transaction_reversals v JOIN accounting.bank_transactions h ON h.company_id=v.company_id AND h.id=v.original_id JOIN accounting.bank_transaction_lines l ON l.company_id=h.company_id AND l.transaction_id=h.id;
CREATE VIEW accounting.bank_transaction_plan WITH(security_invoker=true)AS
 SELECT company_id,id AS source_document_id,bank_account_id AS account_id,CASE WHEN kind='RECEIVE'THEN gross ELSE 0 END AS debit,CASE WHEN kind IN('PAY','TRANSFER')THEN gross ELSE 0 END AS credit FROM accounting.bank_transactions
 UNION ALL SELECT company_id,id,counter_bank_account_id,gross,0 FROM accounting.bank_transactions WHERE kind='TRANSFER'
 UNION ALL SELECT l.company_id,l.transaction_id,l.account_id,CASE WHEN h.kind='PAY'THEN l.net+l.tax-l.recoverable_tax ELSE 0 END,CASE WHEN h.kind='RECEIVE'THEN l.net ELSE 0 END FROM accounting.bank_transaction_lines l JOIN accounting.bank_transactions h ON h.company_id=l.company_id AND h.id=l.transaction_id
 UNION ALL SELECT l.company_id,l.transaction_id,l.tax_account_id,CASE WHEN h.kind='PAY'THEN l.recoverable_tax ELSE 0 END,CASE WHEN h.kind='RECEIVE'THEN l.tax ELSE 0 END FROM accounting.bank_transaction_lines l JOIN accounting.bank_transactions h ON h.company_id=l.company_id AND h.id=l.transaction_id WHERE l.tax_account_id IS NOT NULL AND CASE WHEN h.kind='PAY'THEN l.recoverable_tax ELSE l.tax END>0;
CREATE FUNCTION accounting.validate_general_banking()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE c uuid:=NEW.company_id;doc uuid;h accounting.bank_transactions;rv accounting.bank_transaction_reversals;j uuid;reversed boolean:=false;BEGIN
 IF TG_TABLE_NAME='bank_transactions'THEN doc:=NEW.id;ELSIF TG_TABLE_NAME='bank_transaction_lines'THEN doc:=NEW.transaction_id;ELSIF TG_TABLE_NAME='bank_transaction_reversals'THEN doc:=NEW.id;ELSIF TG_TABLE_NAME='posting_batches'THEN doc:=NEW.source_document_id;ELSE SELECT b.source_document_id INTO doc FROM accounting.journal_entries e JOIN accounting.posting_batches b ON b.company_id=e.company_id AND b.id=e.posting_batch_id WHERE e.company_id=c AND e.id=NEW.journal_entry_id;END IF;
 SELECT*INTO h FROM accounting.bank_transactions WHERE company_id=c AND id=doc;
 IF NOT FOUND THEN SELECT*INTO rv FROM accounting.bank_transaction_reversals WHERE company_id=c AND id=doc;IF NOT FOUND THEN RETURN NULL;END IF;SELECT*INTO h FROM accounting.bank_transactions WHERE company_id=c AND id=rv.original_id;reversed:=true;END IF;
 j:=CASE WHEN reversed THEN rv.journal_entry_id ELSE h.journal_entry_id END;
 IF NOT EXISTS(SELECT 1 FROM platform.documents WHERE company_id=c AND id=doc AND state='POSTED'AND business_date=h.occurred_on AND document_type=CASE WHEN reversed THEN'BANK_TRANSACTION_REVERSAL'ELSE'BANK_'||h.kind END)OR(SELECT count(*)FROM accounting.posting_batches WHERE company_id=c AND source_document_id=doc)<>1 OR NOT EXISTS(SELECT 1 FROM accounting.journal_entries e JOIN accounting.posting_batches b ON b.company_id=e.company_id AND b.id=e.posting_batch_id WHERE e.company_id=c AND e.id=j AND e.posting_date=h.occurred_on AND b.source_document_id=doc AND b.source_version=1 AND b.posting_kind=CASE WHEN reversed THEN'BANK_TRANSACTION_REVERSAL'ELSE'BANK_'||h.kind END)THEN RAISE EXCEPTION 'General banking source and posting do not agree' USING ERRCODE='23514';END IF;
 IF(h.kind='TRANSFER'AND EXISTS(SELECT 1 FROM accounting.bank_transaction_lines WHERE company_id=c AND transaction_id=h.id))OR(h.kind<>'TRANSFER'AND(h.gross<>(SELECT coalesce(sum(net+tax),0)FROM accounting.bank_transaction_lines WHERE company_id=c AND transaction_id=h.id)OR EXISTS(SELECT 1 FROM accounting.bank_transaction_lines l JOIN accounting.accounts a ON a.company_id=l.company_id AND a.id=l.account_id WHERE l.company_id=c AND l.transaction_id=h.id AND(a.control_kind IS NOT NULL OR a.kind NOT IN('ASSET','LIABILITY','EQUITY','REVENUE','EXPENSE')))))THEN RAISE EXCEPTION 'Invalid general banking source lines' USING ERRCODE='23514';END IF;
 IF EXISTS(WITH expected AS(SELECT account_id,sum(CASE WHEN reversed THEN credit ELSE debit END)AS debit,sum(CASE WHEN reversed THEN debit ELSE credit END)AS credit FROM accounting.bank_transaction_plan WHERE company_id=c AND source_document_id=h.id GROUP BY account_id),actual AS(SELECT account_id,sum(debit)AS debit,sum(credit)AS credit FROM accounting.journal_lines WHERE company_id=c AND journal_entry_id=j GROUP BY account_id)SELECT 1 FROM expected e FULL JOIN actual a USING(account_id)WHERE coalesce(e.debit,0)<>coalesce(a.debit,0)OR coalesce(e.credit,0)<>coalesce(a.credit,0))OR EXISTS(SELECT 1 FROM accounting.journal_lines WHERE company_id=c AND journal_entry_id=j AND(party_id IS NOT NULL OR source_line_id IS NOT NULL))THEN RAISE EXCEPTION 'General banking journal differs from its source' USING ERRCODE='23514';END IF;RETURN NULL;END $$;
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['bank_transactions','bank_transaction_lines','bank_transaction_reversals','posting_batches','journal_lines']LOOP EXECUTE format('CREATE CONSTRAINT TRIGGER general_banking_proof AFTER INSERT ON accounting.%I DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION accounting.validate_general_banking()',t);END LOOP;END $$;
CREATE FUNCTION accounting.guard_general_banking_document()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN IF EXISTS(SELECT 1 FROM accounting.bank_transactions WHERE company_id=OLD.company_id AND id=OLD.id)OR EXISTS(SELECT 1 FROM accounting.bank_transaction_reversals WHERE company_id=OLD.company_id AND id=OLD.id)THEN IF TG_OP='DELETE'OR OLD.state='POSTED'THEN RAISE EXCEPTION 'Posted general banking documents are immutable; use reversal' USING ERRCODE='HR409';END IF;END IF;RETURN coalesce(NEW,OLD);END $$;
CREATE TRIGGER general_banking_document BEFORE UPDATE OR DELETE ON platform.documents FOR EACH ROW EXECUTE FUNCTION accounting.guard_general_banking_document();

CREATE FUNCTION accounting.post_general_banking(p_kind text,p_bank uuid,p_other uuid,p_date date,p_reference text,p_reason text,p_items jsonb,p_amount numeric,p_boundary text,p_confirm boolean,p_evidence text,p_held date,p_statement uuid DEFAULT NULL,p_statement_version bigint DEFAULT NULL)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
#variable_conflict use_variable
DECLARE c uuid:=core.current_company();co core.companies;id uuid:=gen_random_uuid();j uuid;x jsonb;a accounting.accounts;t accounting.tax_codes;rate numeric;n numeric;tax numeric;rec numeric;percent numeric;gross numeric:=0;ta uuid;rows jsonb:='[]';journal jsonb:='[]';idx int:=0;bk uuid;sl accounting.bank_statement_lines;st accounting.bank_statement_controls;used numeric;matchid uuid;cashid uuid;allocations jsonb;included int;BEGIN
 PERFORM accounting.require_general_banking(CASE p_kind WHEN'TRANSFER'THEN'accounting.bank_transactions.transfer'ELSE'accounting.bank_transactions.post'END);PERFORM accounting.bas_lock(c,false);
 IF p_kind IS NULL OR p_kind NOT IN('RECEIVE','PAY','TRANSFER')OR p_bank IS NULL OR p_date IS NULL OR p_date<'0002-01-01'OR p_reference IS NULL OR length(btrim(p_reference))NOT BETWEEN 1 AND 200 OR p_reason IS NULL OR length(btrim(p_reason))NOT BETWEEN 1 AND 2000 OR((p_kind='TRANSFER')IS DISTINCT FROM(p_other IS NOT NULL))OR p_other=p_bank THEN RAISE EXCEPTION 'Valid kind, banks, date, reference and reason required' USING ERRCODE='HR422';END IF;
 FOR bk IN SELECT DISTINCT v FROM unnest(ARRAY[p_bank,p_other])v WHERE v IS NOT NULL ORDER BY v LOOP PERFORM accounting.lock_bank_reconciliation(bk);PERFORM accounting.resolve_bank(bk);PERFORM 1 FROM accounting.cash_flow_scopes WHERE company_id=c AND bank_account_id=bk AND NOT review_required FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Confirm cash-equivalent scope before posting' USING ERRCODE='HR409';END IF;END LOOP;
 SELECT*INTO co FROM core.companies WHERE core.companies.id=c;IF p_date>(now()AT TIME ZONE co.timezone)::date THEN RAISE EXCEPTION 'Future cash transactions are not allowed' USING ERRCODE='HR422';END IF;
 IF NOT EXISTS(SELECT 1 FROM accounting.periods q WHERE q.company_id=c AND q.state='OPEN'AND q.starts_on<=p_date AND q.ends_on>p_date)THEN RAISE EXCEPTION 'Open accounting period required' USING ERRCODE='HR409';END IF;
 IF (p_statement IS NULL)IS DISTINCT FROM(p_statement_version IS NULL)THEN RAISE EXCEPTION 'Statement line and version are paired' USING ERRCODE='HR422';END IF;
 IF p_statement IS NOT NULL THEN
 PERFORM accounting.require_general_banking('accounting.bank_transactions.classify');PERFORM accounting.require_bank_reconciliation_access('accounting.bank_statements.match',p_bank);
 SELECT*INTO sl FROM accounting.bank_statement_lines WHERE company_id=c AND accounting.bank_statement_lines.id=p_statement;IF NOT FOUND THEN RAISE EXCEPTION 'Statement line unavailable' USING ERRCODE='HT404';END IF;
 SELECT*INTO st FROM accounting.bank_statement_controls WHERE company_id=c AND accounting.bank_statement_controls.id=sl.statement_id FOR UPDATE;
 IF p_kind='TRANSFER'OR sl.bank_account_id<>p_bank OR sl.transaction_date<>p_date OR(p_kind='RECEIVE')<>(sl.amount>0)THEN RAISE EXCEPTION 'Classification must use the statement bank, direction and date' USING ERRCODE='HR422';END IF;
 IF st.state<>'OPEN'OR st.version IS DISTINCT FROM p_statement_version THEN RAISE EXCEPTION 'Statement changed or closed' USING ERRCODE='HR409';END IF;
 END IF;
 IF p_kind='TRANSFER'THEN
 IF p_items IS NULL OR p_items<>'[]'::jsonb OR p_amount IS NULL OR p_amount<=0 OR p_amount<>round(p_amount,2)OR p_amount>999999999999999999.99 OR p_evidence IS NOT NULL OR p_held IS NOT NULL OR p_confirm IS DISTINCT FROM false THEN RAISE EXCEPTION 'Transfer requires a positive AUD amount and no sales/purchase tax lines' USING ERRCODE='HR422';END IF;
 gross:=p_amount;SELECT count(*)INTO included FROM accounting.cash_flow_scopes sc WHERE sc.company_id=c AND sc.bank_account_id IN(p_bank,p_other)AND sc.included;
 IF included=1 AND(p_boundary IS NULL OR p_boundary NOT IN('OPERATING','INVESTING','FINANCING'))OR included<>1 AND p_boundary IS NOT NULL THEN RAISE EXCEPTION 'Explicit activity is required only when transfer crosses the cash-equivalent boundary' USING ERRCODE='HR422';END IF;
 journal:=jsonb_build_array(jsonb_build_object('accountId',p_bank,'credit',gross),jsonb_build_object('accountId',p_other,'debit',gross));
 ELSE
 IF co.gst_registered IS NULL OR co.gst_basis IS NULL OR p_confirm IS DISTINCT FROM true OR p_amount IS NOT NULL OR p_boundary IS NOT NULL OR p_items IS NULL OR jsonb_typeof(p_items)<>'array'OR jsonb_array_length(p_items)NOT BETWEEN 1 AND 50 OR(p_evidence IS NULL)<>(p_held IS NULL)OR p_evidence IS NOT NULL AND(length(btrim(p_evidence))NOT BETWEEN 1 AND 500 OR p_held>p_date OR p_held<'0002-01-01')THEN RAISE EXCEPTION 'Confirm registration and no prior invoice, claim or posting; provide settled lines and paired tax evidence' USING ERRCODE='HR422';END IF;
 IF co.gst_basis='NON_CASH'AND p_held IS NOT NULL AND p_held<>p_date THEN RAISE EXCEPTION 'Earlier tax invoices require supplier-bill attribution; this cash source must have no earlier invoice' USING ERRCODE='HR422';END IF;
 FOR x IN SELECT*FROM jsonb_array_elements(p_items)LOOP
 idx:=idx+1;n:=(x->>'net')::numeric;tax:=(x->>'tax')::numeric;rec:=coalesce((x->>'recoverableTax')::numeric,CASE WHEN p_kind='PAY'THEN tax ELSE 0 END);percent:=coalesce((x->>'inputTaxedPercent')::numeric,0);
 IF n IS NULL OR n<=0 OR n>999999999999999999.99 OR n<>round(n,2)OR tax IS NULL OR tax<0 OR tax>999999999999999999.99 OR tax<>round(tax,2)OR rec<0 OR rec>tax OR rec<>round(rec,2)OR percent<0 OR percent>100 OR percent<>round(percent,4)OR nullif(btrim(x->>'description'),'')IS NULL OR length(x->>'description')>500 OR(x->>'basClass')IS NULL OR(x->>'cashFlowCategory')IS NULL OR(x->>'cashFlowCategory')NOT IN('OPERATING','INVESTING','FINANCING')THEN RAISE EXCEPTION 'Invalid settled line amounts, purpose, description or cash activity' USING ERRCODE='HR422';END IF;
 SELECT*INTO a FROM accounting.accounts WHERE company_id=c AND accounting.accounts.id=(x->>'accountId')::uuid AND active AND control_kind IS NULL FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Active non-control offset account required; use invoice, stock or settlement workflows for control balances' USING ERRCODE='HR422';END IF;
 IF EXISTS(SELECT 1 FROM accounting.bas_tax_roles br WHERE br.company_id=c AND br.account_id=a.id)OR EXISTS(SELECT 1 FROM accounting.account_mappings m WHERE m.company_id=c AND m.account_id=a.id AND m.purpose IN('CUSTOMER_ADVANCES','SUPPLIER_ADVANCES','PURCHASE_RETURN_CLEARING'))THEN RAISE EXCEPTION 'Protected tax, advance or return clearing accounts require their source workflow' USING ERRCODE='HR422';END IF;
 SELECT*INTO t FROM accounting.tax_codes WHERE company_id=c AND accounting.tax_codes.id=(x->>'taxCodeId')::uuid FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Active company tax code required' USING ERRCODE='HR422';END IF;
 SELECT r.rate INTO rate FROM accounting.tax_rates r WHERE r.company_id=c AND r.tax_code_id=t.id AND r.effective_from<=p_date AND(r.effective_to IS NULL OR r.effective_to>p_date)ORDER BY r.effective_from DESC LIMIT 1;
 IF rate IS NULL OR(t.category='TAXABLE'AND(rate<>0.10 OR tax<>round(n*rate,2)))OR(t.category<>'TAXABLE'AND tax<>0)OR(NOT co.gst_registered AND(t.category<>'OUT_OF_SCOPE'OR tax<>0))THEN RAISE EXCEPTION 'Tax must match the effective standard AU tax code; unregistered cash uses out-of-scope coding' USING ERRCODE='HR422';END IF;
 IF p_kind='RECEIVE'THEN
 IF rec<>0 OR percent<>0 OR NOT((a.kind='REVENUE'AND((t.category='TAXABLE'AND x->>'basClass'='TAXABLE')OR(t.category='GST_FREE'AND x->>'basClass'IN('EXPORT','OTHER_GST_FREE'))OR(t.category='INPUT_TAXED'AND x->>'basClass'='INPUT_TAXED')OR(t.category='OUT_OF_SCOPE'AND x->>'basClass'='EXCLUDED')))OR(a.kind IN('ASSET','LIABILITY','EQUITY')AND t.category='OUT_OF_SCOPE'AND x->>'basClass'='EXCLUDED'))THEN RAISE EXCEPTION 'Receipt account, GST category and explicit BAS sales classification must agree' USING ERRCODE='HR422';END IF;
 ELSE
 IF NOT((a.kind='EXPENSE'AND x->>'basClass'IN('NON_CAPITAL','EXCLUDED'))OR(a.kind='ASSET'AND x->>'basClass'IN('CAPITAL','EXCLUDED'))OR(a.kind IN('LIABILITY','EQUITY')AND x->>'basClass'='EXCLUDED'))OR(x->>'basClass'='EXCLUDED'AND(tax<>0 OR t.category<>'OUT_OF_SCOPE'))OR(rec>0 AND(p_evidence IS NULL OR NOT co.gst_registered))THEN RAISE EXCEPTION 'Payment purpose, non-control account, GST and tax evidence must agree' USING ERRCODE='HR422';END IF;
 END IF;
 ta:=NULL;IF(CASE WHEN p_kind='RECEIVE'THEN tax ELSE rec END)>0 THEN
 SELECT CASE WHEN p_kind='RECEIVE'THEN m.output_account_id ELSE m.input_account_id END INTO ta FROM accounting.tax_account_mappings m WHERE m.company_id=c AND m.tax_code_id=t.id;
 PERFORM 1 FROM accounting.accounts WHERE company_id=c AND accounting.accounts.id=ta AND active AND control_kind='GST'AND kind=CASE WHEN p_kind='RECEIVE'THEN'LIABILITY'ELSE'ASSET'END FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Active mapped GST control account required' USING ERRCODE='HR422';END IF;END IF;
 gross:=gross+n+tax;IF gross>999999999999999999.99 THEN RAISE EXCEPTION 'Transaction total exceeds storage limit' USING ERRCODE='HR422';END IF;
 journal:=journal||jsonb_build_array(jsonb_build_object('accountId',a.id,'debit',CASE WHEN p_kind='PAY'THEN n+tax-rec ELSE 0 END,'credit',CASE WHEN p_kind='RECEIVE'THEN n ELSE 0 END));
 IF ta IS NOT NULL THEN journal:=journal||jsonb_build_array(jsonb_build_object('accountId',ta,'debit',CASE WHEN p_kind='PAY'THEN rec ELSE 0 END,'credit',CASE WHEN p_kind='RECEIVE'THEN tax ELSE 0 END));END IF;
 rows:=rows||jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'lineNo',idx,'accountId',a.id,'description',btrim(x->>'description'),'net',n,'tax',tax,'recoverableTax',rec,'taxCodeId',t.id,'taxCategory',t.category,'taxRate',rate,'taxAccountId',ta,'basClass',x->>'basClass','inputTaxedPercent',percent,'cashFlowCategory',x->>'cashFlowCategory','snapshot',jsonb_build_object('accountCode',a.code,'accountKind',a.kind,'taxCode',t.code,'taxCategory',t.category,'taxRate',rate,'gstRegistered',co.gst_registered,'gstBasis',co.gst_basis,'noPriorPostingConfirmed',true,'taxInvoiceReference',p_evidence,'taxInvoiceHeldOn',p_held)));
 END LOOP;
 journal:=journal||jsonb_build_array(jsonb_build_object('accountId',p_bank,'debit',CASE WHEN p_kind='RECEIVE'THEN gross ELSE 0 END,'credit',CASE WHEN p_kind='PAY'THEN gross ELSE 0 END));
 END IF;
 IF sl.id IS NOT NULL THEN SELECT coalesce(sum(v.amount),0)INTO used FROM accounting.bank_match_allocations v JOIN accounting.active_bank_matches m ON m.company_id=v.company_id AND m.id=v.match_id WHERE m.company_id=c AND m.statement_line_id=sl.id;IF gross>abs(sl.amount)-used THEN RAISE EXCEPTION 'Classification exceeds unmatched statement remainder' USING ERRCODE='HR409';END IF;END IF;
 INSERT INTO platform.documents(id,company_id,document_type,number,business_date,state,created_by)VALUES(id,c,'BANK_'||p_kind,'BT-'||id::text,p_date,'CONFIRMED',core.current_actor());
 j:=accounting.post_journal(id,1,'BANK_'||p_kind,p_date,btrim(p_reason),journal);
 INSERT INTO accounting.bank_transactions(id,company_id,kind,bank_account_id,counter_bank_account_id,occurred_on,reference,reason,gst_basis,gst_registered,gross,journal_entry_id,statement_line_id,created_by)VALUES(id,c,p_kind,p_bank,p_other,p_date,btrim(p_reference),btrim(p_reason),coalesce(co.gst_basis,'NON_CASH'),coalesce(co.gst_registered,false),gross,j,p_statement,core.current_actor());
 INSERT INTO accounting.bank_transaction_lines(id,company_id,transaction_id,line_no,account_id,description,net,tax,recoverable_tax,tax_code_id,tax_category,tax_rate,tax_account_id,bas_class,input_taxed_percent,cash_flow_category,snapshot)SELECT(entry.value->>'id')::uuid,c,id,(entry.value->>'lineNo')::int,(entry.value->>'accountId')::uuid,entry.value->>'description',(entry.value->>'net')::numeric,(entry.value->>'tax')::numeric,(entry.value->>'recoverableTax')::numeric,(entry.value->>'taxCodeId')::uuid,entry.value->>'taxCategory',(entry.value->>'taxRate')::numeric,(entry.value->>'taxAccountId')::uuid,entry.value->>'basClass',(entry.value->>'inputTaxedPercent')::numeric,entry.value->>'cashFlowCategory',entry.value->'snapshot'FROM jsonb_array_elements(rows)AS entry(value);
 UPDATE platform.documents SET state='POSTED'WHERE company_id=c AND platform.documents.id=id;
 IF p_kind<>'TRANSFER'THEN SELECT l.id INTO cashid FROM accounting.journal_lines l JOIN accounting.cash_flow_scopes sc ON sc.company_id=l.company_id AND sc.bank_account_id=l.account_id AND sc.included WHERE l.company_id=c AND l.journal_entry_id=j AND l.account_id=p_bank;
 IF cashid IS NOT NULL THEN SELECT jsonb_agg(jsonb_build_object('journalLineId',cashid,'category',category,'amount',amount))INTO allocations FROM(SELECT entry.value->>'cashFlowCategory'AS category,sum((entry.value->>'net')::numeric+(entry.value->>'tax')::numeric)AS amount FROM jsonb_array_elements(rows)AS entry(value) GROUP BY entry.value->>'cashFlowCategory')q;PERFORM accounting.classify_cash_flow(j,0,'CUSTOM',p_reason,allocations);END IF;
 ELSIF included=1 THEN SELECT jsonb_agg(jsonb_build_object('journalLineId',l.id,'category',p_boundary,'amount',abs(l.debit-l.credit)))INTO allocations FROM accounting.journal_lines l JOIN accounting.cash_flow_scopes sc ON sc.company_id=l.company_id AND sc.bank_account_id=l.account_id AND sc.included WHERE l.company_id=c AND l.journal_entry_id=j;PERFORM accounting.classify_cash_flow(j,0,'CUSTOM',p_reason,allocations);END IF;
 IF sl.id IS NOT NULL THEN SELECT l.id INTO cashid FROM accounting.journal_lines l WHERE l.company_id=c AND l.journal_entry_id=j AND l.account_id=p_bank;matchid:=accounting.match_bank_line(sl.id,p_statement_version,'BT-'||id::text,p_reason,jsonb_build_array(jsonb_build_object('journalLineId',cashid,'amount',gross)));END IF;
 RETURN id;END $$;
CREATE FUNCTION accounting.reverse_general_banking(p_id uuid,p_version bigint,p_reference text,p_reason text)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$#variable_conflict use_variable
DECLARE c uuid:=core.current_company();h accounting.bank_transactions;d platform.documents;bk uuid;id uuid:=gen_random_uuid();j uuid;rows jsonb;BEGIN
 PERFORM accounting.require_general_banking('accounting.bank_transactions.reverse');PERFORM accounting.bas_lock(c,false);SELECT*INTO h FROM accounting.bank_transactions WHERE company_id=c AND accounting.bank_transactions.id=p_id;IF NOT FOUND THEN RAISE EXCEPTION 'Bank transaction unavailable' USING ERRCODE='HT404';END IF;
 FOR bk IN SELECT DISTINCT v FROM unnest(ARRAY[h.bank_account_id,h.counter_bank_account_id])v WHERE v IS NOT NULL ORDER BY v LOOP PERFORM accounting.lock_bank_reconciliation(bk);END LOOP;
 SELECT*INTO d FROM platform.documents WHERE company_id=c AND platform.documents.id=p_id FOR UPDATE;
 IF d.version IS DISTINCT FROM p_version OR EXISTS(SELECT 1 FROM accounting.bank_transaction_reversals WHERE company_id=c AND original_id=p_id)THEN RAISE EXCEPTION 'Transaction changed or already reversed' USING ERRCODE='HR409';END IF;
 IF p_reference IS NULL OR length(btrim(p_reference))NOT BETWEEN 1 AND 200 OR p_reason IS NULL OR length(btrim(p_reason))NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Reference and correction reason required' USING ERRCODE='HR422';END IF;
 IF EXISTS(SELECT 1 FROM accounting.journal_lines l JOIN accounting.bank_match_allocations a ON a.company_id=l.company_id AND a.journal_line_id=l.id JOIN accounting.active_bank_matches m ON m.company_id=a.company_id AND m.id=a.match_id WHERE l.company_id=c AND l.journal_entry_id=h.journal_entry_id)THEN RAISE EXCEPTION 'Release bank matches and reopen reconciliations before correcting this source' USING ERRCODE='HR409';END IF;
 IF NOT EXISTS(SELECT 1 FROM accounting.periods q WHERE q.company_id=c AND q.state='OPEN'AND q.starts_on<=h.occurred_on AND q.ends_on>h.occurred_on)THEN RAISE EXCEPTION 'Reopen the original accounting period before correction' USING ERRCODE='HR409';END IF;
 SELECT jsonb_agg(jsonb_build_object('accountId',account_id,'debit',credit,'credit',debit)ORDER BY account_id,l.id)INTO rows FROM accounting.journal_lines l WHERE company_id=c AND journal_entry_id=h.journal_entry_id;
 INSERT INTO platform.documents(id,company_id,document_type,number,business_date,state,created_by)VALUES(id,c,'BANK_TRANSACTION_REVERSAL','BTR-'||id::text,h.occurred_on,'CONFIRMED',core.current_actor());
 j:=accounting.post_journal(id,1,'BANK_TRANSACTION_REVERSAL',h.occurred_on,btrim(p_reason),rows);
 INSERT INTO accounting.bank_transaction_reversals(id,company_id,original_id,reference,reason,journal_entry_id,created_by)VALUES(id,c,p_id,btrim(p_reference),btrim(p_reason),j,core.current_actor());
 UPDATE platform.documents SET state='POSTED'WHERE company_id=c AND platform.documents.id=id;RETURN id;END $$;

CREATE OR REPLACE VIEW accounting.bas_tax_events WITH(security_invoker=true)AS
 SELECT g.company_id,'SALES_ATTRIBUTION'::text AS source_type,g.id AS source_id,g.source_document_id,'SALES'::text AS side,g.gst_basis,g.attribution_date,g.tax_code_id,g.kind,g.amount AS source_gross,g.gst_amount,g.gst_amount AS label_1a,0::numeric AS label_1b FROM accounting.gst_attributions g
 UNION ALL
 SELECT g.company_id,'SALES_ADJUSTMENT',g.id,g.source_document_id,'SALES',g.gst_basis,g.adjustment_date,g.tax_code_id,g.kind,g.amount,g.gst_amount,
 CASE WHEN g.kind IN('RECEIPT_REVERSAL','ADVANCE_UNAPPLICATION') THEN g.gst_amount WHEN g.kind='CUSTOMER_REFUND_REVERSAL' THEN 0 WHEN g.kind='CREDIT_UNAPPLICATION' THEN CASE WHEN EXISTS(SELECT 1 FROM sales.credit_unapplications u JOIN sales.credit_application_lines l ON l.company_id=u.company_id AND l.application_id=u.application_id WHERE u.company_id=g.company_id AND u.id=g.source_document_id AND l.target_invoice_line_id=g.invoice_line_id) THEN g.gst_amount ELSE 0 END ELSE greatest(g.gst_amount,0) END,
 CASE WHEN g.kind IN('RECEIPT_REVERSAL','ADVANCE_UNAPPLICATION') THEN 0 WHEN g.kind='CUSTOMER_REFUND_REVERSAL' THEN -g.gst_amount WHEN g.kind='CREDIT_UNAPPLICATION' THEN CASE WHEN EXISTS(SELECT 1 FROM sales.credit_unapplications u JOIN sales.credit_application_lines l ON l.company_id=u.company_id AND l.application_id=u.application_id WHERE u.company_id=g.company_id AND u.id=g.source_document_id AND l.source_invoice_line_id=g.invoice_line_id) THEN -g.gst_amount ELSE 0 END ELSE greatest(-g.gst_amount,0) END FROM accounting.gst_adjustments g
 UNION ALL
 SELECT g.company_id,'PURCHASE_INVOICE',g.id,l.bill_id,'PURCHASES',g.gst_basis,g.attribution_date,g.tax_code_id,'NON_CASH_BILL',l.net+l.tax,g.recoverable_tax,0,g.recoverable_tax FROM accounting.purchase_gst_entries g JOIN purchase.bill_lines l ON l.company_id=g.company_id AND l.id=g.bill_line_id WHERE g.gst_basis='NON_CASH' AND g.attribution_date IS NOT NULL
 UNION ALL
 SELECT g.company_id,'PURCHASE_ATTRIBUTION',g.id,g.source_document_id,'PURCHASES','CASH',g.attribution_date,e.tax_code_id,'CASH_PAYMENT',g.amount,g.gst_amount,0,g.gst_amount FROM accounting.purchase_gst_attributions g JOIN accounting.purchase_gst_entries e ON e.company_id=g.company_id AND e.bill_line_id=g.bill_line_id
 UNION ALL
 SELECT g.company_id,'PURCHASE_ADJUSTMENT',g.id,g.source_document_id,'PURCHASES',g.gst_basis,g.adjustment_date,e.tax_code_id,g.kind,g.amount,g.gst_amount,
 CASE WHEN g.kind IN('SUPPLIER_PAYMENT_REVERSAL','SUPPLIER_ADVANCE_UNAPPLICATION') THEN 0 WHEN g.kind='SUPPLIER_REFUND_REVERSAL' THEN -g.gst_amount WHEN g.kind='CREDIT_UNAPPLICATION' THEN CASE WHEN EXISTS(SELECT 1 FROM purchase.credit_unapplications u JOIN purchase.credit_application_lines l ON l.company_id=u.company_id AND l.application_id=u.application_id WHERE u.company_id=g.company_id AND u.id=g.source_document_id AND l.source_bill_line_id=g.bill_line_id) THEN -g.gst_amount ELSE 0 END ELSE greatest(-g.gst_amount,0) END,
 CASE WHEN g.kind IN('SUPPLIER_PAYMENT_REVERSAL','SUPPLIER_ADVANCE_UNAPPLICATION') THEN g.gst_amount WHEN g.kind='SUPPLIER_REFUND_REVERSAL' THEN 0 WHEN g.kind='CREDIT_UNAPPLICATION' THEN CASE WHEN EXISTS(SELECT 1 FROM purchase.credit_unapplications u JOIN purchase.credit_application_lines l ON l.company_id=u.company_id AND l.application_id=u.application_id WHERE u.company_id=g.company_id AND u.id=g.source_document_id AND l.target_bill_line_id=g.bill_line_id) THEN g.gst_amount ELSE 0 END ELSE greatest(g.gst_amount,0) END FROM accounting.purchase_gst_adjustments g JOIN accounting.purchase_gst_entries e ON e.company_id=g.company_id AND e.bill_line_id=g.bill_line_id
 UNION ALL SELECT e.company_id,CASE WHEN e.is_reversal THEN'BANK_TAX_REVERSAL'ELSE'BANK_TAX'END,e.source_id,e.source_document_id,CASE WHEN e.kind='RECEIVE'THEN'SALES'ELSE'PURCHASES'END,e.gst_basis,e.event_date,e.tax_code_id,'SETTLED_CASH',e.net+e.tax,(CASE WHEN e.kind='RECEIVE'THEN e.tax ELSE e.recoverable_tax END)::numeric(20,2),CASE WHEN e.kind='RECEIVE'THEN e.tax ELSE 0 END,CASE WHEN e.kind='PAY'THEN e.recoverable_tax ELSE 0 END FROM accounting.bank_transaction_events e WHERE e.gst_registered;

CREATE OR REPLACE VIEW accounting.bas_expected_gl WITH(security_invoker=true)AS
SELECT g.company_id AS company_id,g.output_account_id AS account_id,l.invoice_id AS source_document_id,i.invoice_date AS posting_date,-g.tax AS debit_signed FROM accounting.sales_gst_entries g JOIN sales.invoice_lines l ON l.company_id=g.company_id AND l.id=g.invoice_line_id JOIN sales.invoices i ON i.company_id=l.company_id AND i.id=l.invoice_id
UNION ALL
SELECT l.company_id AS company_id,g.output_account_id AS account_id,l.credit_note_id AS source_document_id,d.business_date AS posting_date,l.tax AS debit_signed FROM sales.credit_note_lines l JOIN accounting.sales_gst_entries g ON g.company_id=l.company_id AND g.invoice_line_id=l.invoice_line_id JOIN platform.documents d ON d.company_id=l.company_id AND d.id=l.credit_note_id
UNION ALL
SELECT a.company_id AS company_id,a.output_account_id AS account_id,a.receipt_id AS source_document_id,r.received_on AS posting_date,-a.gst_amount AS debit_signed FROM accounting.customer_advances a JOIN accounting.customer_receipts r ON r.company_id=a.company_id AND r.id=a.receipt_id
UNION ALL
SELECT a.company_id AS company_id,a.clearing_account_id AS account_id,a.receipt_id AS source_document_id,r.received_on AS posting_date,a.gst_amount AS debit_signed FROM accounting.customer_advances a JOIN accounting.customer_receipts r ON r.company_id=a.company_id AND r.id=a.receipt_id
UNION ALL
SELECT c.company_id AS company_id,g.output_account_id AS account_id,l.invoice_id AS source_document_id,i.invoice_date AS posting_date,c.gst_amount AS debit_signed FROM accounting.advance_gst_clearings c JOIN accounting.customer_advances a ON a.company_id=c.company_id AND a.id=c.advance_id JOIN sales.invoice_lines l ON l.company_id=c.company_id AND l.id=c.invoice_line_id JOIN sales.invoices i ON i.company_id=l.company_id AND i.id=l.invoice_id JOIN accounting.sales_gst_entries g ON g.company_id=l.company_id AND g.invoice_line_id=l.id
UNION ALL
SELECT c.company_id AS company_id,a.clearing_account_id AS account_id,l.invoice_id AS source_document_id,i.invoice_date AS posting_date,-c.gst_amount AS debit_signed FROM accounting.advance_gst_clearings c JOIN accounting.customer_advances a ON a.company_id=c.company_id AND a.id=c.advance_id JOIN sales.invoice_lines l ON l.company_id=c.company_id AND l.id=c.invoice_line_id JOIN sales.invoices i ON i.company_id=l.company_id AND i.id=l.invoice_id JOIN accounting.sales_gst_entries g ON g.company_id=l.company_id AND g.invoice_line_id=l.id
UNION ALL
SELECT ap.company_id AS company_id,a.output_account_id AS account_id,ap.id AS source_document_id,d.business_date AS posting_date,t.tax AS debit_signed FROM accounting.advance_applications ap JOIN accounting.customer_advances a ON a.company_id=ap.company_id AND a.id=ap.advance_id JOIN accounting.customer_receipts r ON r.company_id=a.company_id AND r.id=a.receipt_id JOIN platform.documents d ON d.company_id=ap.company_id AND d.id=ap.id CROSS JOIN LATERAL(SELECT coalesce(sum(gst_amount),0) AS tax FROM accounting.gst_attributions WHERE company_id=ap.company_id AND source_document_id=ap.id AND kind='ADVANCE_APPLIED') t WHERE a.gst_basis='CASH'
UNION ALL
SELECT ap.company_id AS company_id,a.clearing_account_id AS account_id,ap.id AS source_document_id,d.business_date AS posting_date,-t.tax AS debit_signed FROM accounting.advance_applications ap JOIN accounting.customer_advances a ON a.company_id=ap.company_id AND a.id=ap.advance_id JOIN accounting.customer_receipts r ON r.company_id=a.company_id AND r.id=a.receipt_id JOIN platform.documents d ON d.company_id=ap.company_id AND d.id=ap.id CROSS JOIN LATERAL(SELECT coalesce(sum(gst_amount),0) AS tax FROM accounting.gst_attributions WHERE company_id=ap.company_id AND source_document_id=ap.id AND kind='ADVANCE_APPLIED') t WHERE a.gst_basis='CASH'
UNION ALL
SELECT ap.company_id AS company_id,a.output_account_id AS account_id,ap.id AS source_document_id,coalesce((SELECT min(attribution_date) FROM accounting.gst_attributions WHERE company_id=ap.company_id AND source_document_id=ap.id AND kind='ADVANCE_TRANSFER'),r.received_on) AS posting_date,-(t.tax-ap.consumed_gst) AS debit_signed FROM accounting.advance_applications ap JOIN accounting.customer_advances a ON a.company_id=ap.company_id AND a.id=ap.advance_id JOIN accounting.customer_receipts r ON r.company_id=a.company_id AND r.id=a.receipt_id JOIN platform.documents d ON d.company_id=ap.company_id AND d.id=ap.id CROSS JOIN LATERAL(SELECT coalesce(sum(gst_amount),0) AS tax FROM accounting.gst_attributions WHERE company_id=ap.company_id AND source_document_id=ap.id AND kind='ADVANCE_APPLIED') t WHERE a.gst_basis='CASH'
UNION ALL
SELECT ap.company_id AS company_id,a.clearing_account_id AS account_id,ap.id AS source_document_id,coalesce((SELECT min(attribution_date) FROM accounting.gst_attributions WHERE company_id=ap.company_id AND source_document_id=ap.id AND kind='ADVANCE_TRANSFER'),r.received_on) AS posting_date,t.tax-ap.consumed_gst AS debit_signed FROM accounting.advance_applications ap JOIN accounting.customer_advances a ON a.company_id=ap.company_id AND a.id=ap.advance_id JOIN accounting.customer_receipts r ON r.company_id=a.company_id AND r.id=a.receipt_id JOIN platform.documents d ON d.company_id=ap.company_id AND d.id=ap.id CROSS JOIN LATERAL(SELECT coalesce(sum(gst_amount),0) AS tax FROM accounting.gst_attributions WHERE company_id=ap.company_id AND source_document_id=ap.id AND kind='ADVANCE_APPLIED') t WHERE a.gst_basis='CASH'
UNION ALL
SELECT g.company_id AS company_id,a.output_account_id AS account_id,g.source_document_id AS source_document_id,d.business_date AS posting_date,-g.gst_amount AS debit_signed FROM accounting.gst_adjustments g JOIN accounting.customer_advances a ON a.company_id=g.company_id AND a.id=g.advance_id JOIN platform.documents d ON d.company_id=g.company_id AND d.id=g.source_document_id
UNION ALL
SELECT g.company_id AS company_id,a.clearing_account_id AS account_id,g.source_document_id AS source_document_id,d.business_date AS posting_date,g.gst_amount AS debit_signed FROM accounting.gst_adjustments g JOIN accounting.customer_advances a ON a.company_id=g.company_id AND a.id=g.advance_id JOIN platform.documents d ON d.company_id=g.company_id AND d.id=g.source_document_id
UNION ALL
SELECT g.company_id AS company_id,g.debit_account_id AS account_id,l.bill_id AS source_document_id,d.business_date AS posting_date,g.recoverable_tax AS debit_signed FROM accounting.purchase_gst_entries g JOIN purchase.bill_lines l ON l.company_id=g.company_id AND l.id=g.bill_line_id JOIN platform.documents d ON d.company_id=l.company_id AND d.id=l.bill_id
UNION ALL
SELECT l.company_id AS company_id,g.debit_account_id AS account_id,l.credit_note_id AS source_document_id,d.business_date AS posting_date,-l.recoverable_tax AS debit_signed FROM purchase.supplier_credit_lines l JOIN accounting.purchase_gst_entries g ON g.company_id=l.company_id AND g.bill_line_id=l.bill_line_id JOIN platform.documents d ON d.company_id=l.company_id AND d.id=l.credit_note_id
UNION ALL
SELECT g.company_id AS company_id,g.input_account_id AS account_id,g.source_document_id AS source_document_id,d.business_date AS posting_date,g.gst_amount AS debit_signed FROM accounting.purchase_gst_attributions g JOIN platform.documents d ON d.company_id=g.company_id AND d.id=g.source_document_id
UNION ALL
SELECT g.company_id AS company_id,g.deferred_account_id AS account_id,g.source_document_id AS source_document_id,d.business_date AS posting_date,-g.gst_amount AS debit_signed FROM accounting.purchase_gst_attributions g JOIN platform.documents d ON d.company_id=g.company_id AND d.id=g.source_document_id
UNION ALL
SELECT g.company_id AS company_id,e.input_account_id AS account_id,g.source_document_id AS source_document_id,d.business_date AS posting_date,g.gst_amount AS debit_signed FROM accounting.purchase_gst_adjustments g JOIN accounting.purchase_gst_entries e ON e.company_id=g.company_id AND e.bill_line_id=g.bill_line_id JOIN platform.documents d ON d.company_id=g.company_id AND d.id=g.source_document_id WHERE g.gst_basis='CASH'
UNION ALL
SELECT g.company_id AS company_id,e.debit_account_id AS account_id,g.source_document_id AS source_document_id,d.business_date AS posting_date,-g.gst_amount AS debit_signed FROM accounting.purchase_gst_adjustments g JOIN accounting.purchase_gst_entries e ON e.company_id=g.company_id AND e.bill_line_id=g.bill_line_id JOIN platform.documents d ON d.company_id=g.company_id AND d.id=g.source_document_id WHERE g.gst_basis='CASH'
 UNION ALL SELECT e.company_id,e.tax_account_id,e.source_document_id,e.event_date,CASE WHEN e.kind='RECEIVE'THEN -e.tax ELSE e.recoverable_tax END FROM accounting.bank_transaction_events e WHERE e.tax_account_id IS NOT NULL;

CREATE OR REPLACE VIEW accounting.bas_tax_roles WITH(security_invoker=true)AS
 SELECT company_id,output_account_id AS account_id,'OUTPUT'::text AS role FROM accounting.tax_account_mappings
 UNION SELECT company_id,input_account_id,'INPUT' FROM accounting.tax_account_mappings
 UNION SELECT company_id,output_account_id,'OUTPUT' FROM accounting.sales_gst_entries WHERE output_account_id IS NOT NULL
 UNION SELECT company_id,output_account_id,'OUTPUT' FROM accounting.customer_advances WHERE output_account_id IS NOT NULL
 UNION SELECT company_id,input_account_id,'INPUT' FROM accounting.purchase_gst_entries WHERE input_account_id IS NOT NULL
 UNION SELECT company_id,debit_account_id,'INPUT_DEFERRED' FROM accounting.purchase_gst_entries WHERE gst_basis='CASH' AND recoverable_tax>0
 UNION SELECT company_id,clearing_account_id,'ADVANCE_CLEARING' FROM accounting.customer_advances
 UNION SELECT company_id,account_id,CASE WHEN purpose='GST_ADVANCE_CLEARING' THEN 'ADVANCE_CLEARING' ELSE 'INPUT_DEFERRED' END FROM accounting.account_mappings WHERE purpose IN('GST_ADVANCE_CLEARING','GST_INPUT_DEFERRED')
 UNION ALL SELECT DISTINCT e.company_id,e.tax_account_id,CASE WHEN e.kind='RECEIVE'THEN'OUTPUT'ELSE'INPUT'END FROM accounting.bank_transaction_events e WHERE e.tax_account_id IS NOT NULL;

CREATE OR REPLACE VIEW accounting.bas_cash_sales WITH(security_invoker=true)AS
SELECT x.company_id,'CASH_INVOICE_RECEIPT'::text AS source_type,x.id AS source_id,x.source_document_id AS source_document_id,r.received_on AS event_date,l.tax_code_id AS tax_code_id,x.amount AS gross_amount FROM accounting.payment_allocations x JOIN sales.invoice_lines l ON l.company_id=x.company_id AND l.id=x.invoice_line_id JOIN sales.invoices i ON i.company_id=l.company_id AND i.id=l.invoice_id JOIN accounting.customer_receipts r ON r.company_id=x.company_id AND r.id=x.receipt_id WHERE x.advance_id IS NULL AND i.gst_basis='CASH' AND coalesce((i.issuer_snapshot->>'gstRegistered')::boolean,false)
UNION ALL
SELECT x.company_id,'CASH_ADVANCE_RECEIPT'::text AS source_type,x.id AS source_id,x.receipt_id AS source_document_id,r.received_on AS event_date,x.tax_code_id AS tax_code_id,x.amount AS gross_amount FROM accounting.customer_advances x JOIN accounting.customer_receipts r ON r.company_id=x.company_id AND r.id=x.receipt_id JOIN core.companies c ON c.id=x.company_id WHERE x.gst_basis='CASH' AND c.gst_registered
UNION ALL
SELECT x.company_id,'CASH_INVOICE_RECEIPT_REVERSAL'::text AS source_type,a.id AS source_id,x.id AS source_document_id,d.business_date AS event_date,l.tax_code_id AS tax_code_id,-a.amount AS gross_amount FROM accounting.receipt_reversals x JOIN accounting.payment_allocations a ON a.company_id=x.company_id AND a.receipt_id=x.receipt_id AND a.advance_id IS NULL JOIN sales.invoice_lines l ON l.company_id=a.company_id AND l.id=a.invoice_line_id JOIN sales.invoices i ON i.company_id=l.company_id AND i.id=l.invoice_id JOIN platform.documents d ON d.company_id=x.company_id AND d.id=x.id WHERE i.gst_basis='CASH' AND coalesce((i.issuer_snapshot->>'gstRegistered')::boolean,false)
UNION ALL
SELECT x.company_id,'CASH_ADVANCE_RECEIPT_REVERSAL'::text AS source_type,a.id AS source_id,x.id AS source_document_id,d.business_date AS event_date,a.tax_code_id AS tax_code_id,-a.amount AS gross_amount FROM accounting.receipt_reversals x JOIN accounting.customer_advances a ON a.company_id=x.company_id AND a.receipt_id=x.receipt_id JOIN platform.documents d ON d.company_id=x.company_id AND d.id=x.id JOIN core.companies c ON c.id=x.company_id WHERE a.gst_basis='CASH' AND c.gst_registered
UNION ALL
SELECT x.company_id,'CASH_CREDIT_REFUND'::text AS source_type,x.id AS source_id,x.id AS source_document_id,d.business_date AS event_date,l.tax_code_id AS tax_code_id,-x.amount AS gross_amount FROM accounting.customer_refunds x JOIN sales.credit_note_lines cl ON cl.company_id=x.company_id AND cl.id=x.credit_line_id JOIN sales.invoice_lines l ON l.company_id=cl.company_id AND l.id=cl.invoice_line_id JOIN sales.invoices i ON i.company_id=l.company_id AND i.id=l.invoice_id JOIN platform.documents d ON d.company_id=x.company_id AND d.id=x.id WHERE i.gst_basis='CASH' AND coalesce((i.issuer_snapshot->>'gstRegistered')::boolean,false)
UNION ALL
SELECT x.company_id,'CASH_ADVANCE_REFUND'::text AS source_type,x.id AS source_id,x.id AS source_document_id,d.business_date AS event_date,a.tax_code_id AS tax_code_id,-x.amount AS gross_amount FROM accounting.customer_refunds x JOIN accounting.customer_advances a ON a.company_id=x.company_id AND a.id=x.advance_id JOIN platform.documents d ON d.company_id=x.company_id AND d.id=x.id JOIN core.companies c ON c.id=x.company_id WHERE a.gst_basis='CASH' AND c.gst_registered
UNION ALL
SELECT x.company_id,'CASH_CREDIT_REFUND_REVERSAL'::text AS source_type,x.id AS source_id,x.id AS source_document_id,d.business_date AS event_date,l.tax_code_id AS tax_code_id,rf.amount AS gross_amount FROM accounting.customer_refund_reversals x JOIN accounting.customer_refunds rf ON rf.company_id=x.company_id AND rf.id=x.refund_id JOIN sales.credit_note_lines cl ON cl.company_id=rf.company_id AND cl.id=rf.credit_line_id JOIN sales.invoice_lines l ON l.company_id=cl.company_id AND l.id=cl.invoice_line_id JOIN sales.invoices i ON i.company_id=l.company_id AND i.id=l.invoice_id JOIN platform.documents d ON d.company_id=x.company_id AND d.id=x.id WHERE i.gst_basis='CASH' AND coalesce((i.issuer_snapshot->>'gstRegistered')::boolean,false)
UNION ALL
SELECT x.company_id,'CASH_ADVANCE_REFUND_REVERSAL'::text AS source_type,x.id AS source_id,x.id AS source_document_id,d.business_date AS event_date,a.tax_code_id AS tax_code_id,rf.amount AS gross_amount FROM accounting.customer_refund_reversals x JOIN accounting.customer_refunds rf ON rf.company_id=x.company_id AND rf.id=x.refund_id JOIN accounting.customer_advances a ON a.company_id=rf.company_id AND a.id=rf.advance_id JOIN platform.documents d ON d.company_id=x.company_id AND d.id=x.id JOIN core.companies c ON c.id=x.company_id WHERE a.gst_basis='CASH' AND c.gst_registered
UNION ALL
SELECT x.company_id,'CASH_CREDIT_APPLICATION_SOURCE'::text AS source_type,x.id AS source_id,x.application_id AS source_document_id,d.business_date AS event_date,l.tax_code_id AS tax_code_id,-1*x.amount AS gross_amount FROM sales.credit_application_lines x JOIN sales.invoice_lines l ON l.company_id=x.company_id AND l.id=x.source_invoice_line_id JOIN sales.invoices i ON i.company_id=l.company_id AND i.id=l.invoice_id JOIN platform.documents d ON d.company_id=x.company_id AND d.id=x.application_id WHERE i.gst_basis='CASH' AND coalesce((i.issuer_snapshot->>'gstRegistered')::boolean,false)
UNION ALL
SELECT x.company_id,'CASH_CREDIT_APPLICATION_TARGET'::text AS source_type,x.id AS source_id,x.application_id AS source_document_id,d.business_date AS event_date,l.tax_code_id AS tax_code_id,1*x.amount AS gross_amount FROM sales.credit_application_lines x JOIN sales.invoice_lines l ON l.company_id=x.company_id AND l.id=x.target_invoice_line_id JOIN sales.invoices i ON i.company_id=l.company_id AND i.id=l.invoice_id JOIN platform.documents d ON d.company_id=x.company_id AND d.id=x.application_id WHERE i.gst_basis='CASH' AND coalesce((i.issuer_snapshot->>'gstRegistered')::boolean,false)
UNION ALL
SELECT x.company_id,'CASH_CREDIT_UNAPPLICATION_SOURCE'::text AS source_type,x.id AS source_id,u.id AS source_document_id,d.business_date AS event_date,l.tax_code_id AS tax_code_id,1*x.amount AS gross_amount FROM sales.credit_unapplications u JOIN sales.credit_application_lines x ON x.company_id=u.company_id AND x.application_id=u.application_id JOIN sales.invoice_lines l ON l.company_id=x.company_id AND l.id=x.source_invoice_line_id JOIN sales.invoices i ON i.company_id=l.company_id AND i.id=l.invoice_id JOIN platform.documents d ON d.company_id=x.company_id AND d.id=u.id WHERE i.gst_basis='CASH' AND coalesce((i.issuer_snapshot->>'gstRegistered')::boolean,false)
UNION ALL
SELECT x.company_id,'CASH_CREDIT_UNAPPLICATION_TARGET'::text AS source_type,x.id AS source_id,u.id AS source_document_id,d.business_date AS event_date,l.tax_code_id AS tax_code_id,-1*x.amount AS gross_amount FROM sales.credit_unapplications u JOIN sales.credit_application_lines x ON x.company_id=u.company_id AND x.application_id=u.application_id JOIN sales.invoice_lines l ON l.company_id=x.company_id AND l.id=x.target_invoice_line_id JOIN sales.invoices i ON i.company_id=l.company_id AND i.id=l.invoice_id JOIN platform.documents d ON d.company_id=x.company_id AND d.id=u.id WHERE i.gst_basis='CASH' AND coalesce((i.issuer_snapshot->>'gstRegistered')::boolean,false)
 UNION ALL SELECT e.company_id,CASE WHEN e.is_reversal THEN'BANK_RECEIVE_REVERSAL'ELSE'BANK_RECEIVE'END,e.source_id,e.source_document_id,e.event_date,e.tax_code_id,e.net+e.tax FROM accounting.bank_transaction_events e WHERE e.kind='RECEIVE'AND e.gst_registered AND e.gst_basis='CASH';

CREATE OR REPLACE FUNCTION accounting.bas_turnover(p_from date,p_to date) RETURNS TABLE(company_id uuid,source_type text,source_id uuid,source_document_id uuid,gst_basis text,event_date date,tax_code_id uuid,gross_amount numeric) LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 WITH opening AS MATERIALIZED(SELECT * FROM accounting.bas_non_cash_positions(p_from-1)),closing AS MATERIALIZED(SELECT * FROM accounting.bas_non_cash_positions(p_to-1))
 SELECT x.company_id,x.source_type,x.source_id,x.source_document_id,'CASH',x.event_date,x.tax_code_id,x.gross_amount FROM accounting.bas_cash_sales x WHERE x.company_id=core.current_company() AND x.event_date>=p_from AND x.event_date<p_to
 UNION ALL SELECT coalesce(c.company_id,o.company_id),'NON_CASH_ORDER_CHANGE',coalesce(c.source_id,o.source_id),coalesce(c.source_document_id,o.source_document_id),'NON_CASH',p_to-1,coalesce(c.tax_code_id,o.tax_code_id),coalesce(c.gross_amount,0)-coalesce(o.gross_amount,0) FROM closing c FULL JOIN opening o ON o.company_id=c.company_id AND o.source_id=c.source_id WHERE coalesce(c.gross_amount,0)<>coalesce(o.gross_amount,0)
 UNION ALL SELECT e.company_id,CASE WHEN e.is_reversal THEN'BANK_RECEIVE_REVERSAL'ELSE'BANK_RECEIVE'END,e.source_id,e.source_document_id,e.gst_basis,e.event_date,e.tax_code_id,e.net+e.tax FROM accounting.bank_transaction_events e WHERE e.company_id=core.current_company()AND e.kind='RECEIVE'AND e.gst_registered AND e.gst_basis='NON_CASH'AND e.event_date>=p_from AND e.event_date<p_to
 $$;

CREATE OR REPLACE FUNCTION accounting.bas_full_sales(p_from date,p_to date,p_worksheet boolean) RETURNS TABLE(company_id uuid,source_type text,source_id uuid,source_document_id uuid,gst_basis text,event_date date,tax_code_id uuid,gross_amount numeric) LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT * FROM accounting.bas_turnover(p_from,p_to) WHERE NOT p_worksheet
 UNION ALL SELECT x.company_id,x.source_type,x.source_id,x.source_document_id,'CASH',x.event_date,x.tax_code_id,x.gross_amount FROM accounting.bas_cash_sales x WHERE p_worksheet AND x.company_id=core.current_company() AND x.event_date>=p_from AND x.event_date<p_to AND x.source_type NOT IN('CASH_CREDIT_REFUND','CASH_ADVANCE_REFUND','CASH_CREDIT_REFUND_REVERSAL','CASH_ADVANCE_REFUND_REVERSAL','CASH_CREDIT_APPLICATION_SOURCE','CASH_CREDIT_UNAPPLICATION_SOURCE')
 UNION ALL SELECT coalesce(c.company_id,o.company_id),'NON_CASH_WORKSHEET_CHANGE',coalesce(c.source_id,o.source_id),coalesce(c.source_document_id,o.source_document_id),'NON_CASH',p_to-1,coalesce(c.tax_code_id,o.tax_code_id),coalesce(c.gross_amount,0)-coalesce(o.gross_amount,0) FROM accounting.bas_worksheet_positions(p_to-1)c FULL JOIN accounting.bas_worksheet_positions(p_from-1)o ON o.company_id=c.company_id AND o.source_id=c.source_id WHERE p_worksheet AND coalesce(c.gross_amount,0)<>coalesce(o.gross_amount,0)
 UNION ALL SELECT e.company_id,CASE WHEN e.is_reversal THEN'BANK_RECEIVE_REVERSAL'ELSE'BANK_RECEIVE'END,e.source_id,e.source_document_id,e.gst_basis,e.event_date,e.tax_code_id,e.net+e.tax FROM accounting.bank_transaction_events e WHERE p_worksheet AND e.company_id=core.current_company()AND e.kind='RECEIVE'AND e.gst_registered AND e.gst_basis='NON_CASH'AND e.event_date>=p_from AND e.event_date<p_to
 $$;

CREATE FUNCTION accounting.bank_bas_sales_class(p_type text,p_id uuid,p_code uuid)RETURNS text LANGUAGE sql STABLE SET search_path=pg_catalog AS $$SELECT CASE WHEN p_type IN('BANK_RECEIVE','BANK_RECEIVE_REVERSAL')THEN(SELECT bas_class FROM accounting.bank_transaction_lines WHERE company_id=core.current_company()AND id=p_id)ELSE accounting.bas_sales_class(p_code)END$$;

CREATE OR REPLACE FUNCTION accounting.bas_full_purchase_items(p_from date,p_to date,p_worksheet boolean) RETURNS TABLE(source_type text,source_id uuid,source_document_id uuid,event_date date,bill_line_id uuid,gst_basis text,tax_code_id uuid,purchase_class text,classification_id uuid,classification_revision bigint,gross_amount numeric,g13 numeric,g14 numeric,g15 numeric,issue boolean) LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT e.source_type,e.source_id,e.source_document_id,e.event_date,p.bill_line_id,p.gst_basis,p.tax_code_id,p.purchase_class,p.classification_id,p.classification_revision,e.gross_amount,
 CASE WHEN p.tax>0 AND p.purchase_class<>'EXCLUDED' THEN e.gross_amount*(p.tax-p.recoverable_tax)/p.tax*coalesce(p.input_taxed_percent,0)/100 ELSE 0 END,
 CASE WHEN p.tax=0 AND p.purchase_class<>'EXCLUDED' THEN e.gross_amount ELSE 0 END,
 CASE WHEN p.tax>0 AND p.purchase_class<>'EXCLUDED' THEN e.gross_amount*(p.tax-p.recoverable_tax)/p.tax*(1-coalesce(p.input_taxed_percent,0)/100) ELSE 0 END,
 p.purchase_class='PENDING' OR(p.purchase_class='EXCLUDED' AND p.recoverable_tax>0) OR(p.purchase_class<>'EXCLUDED' AND p.tax>p.recoverable_tax AND p.input_taxed_percent IS NULL)
 FROM accounting.bas_purchase_gross_events e JOIN accounting.bas_purchase_profiles p ON p.company_id=e.company_id AND p.bill_line_id=e.bill_line_id WHERE e.company_id=core.current_company() AND e.event_date>=p_from AND e.event_date<p_to AND(NOT p_worksheet OR NOT e.legal_adjustment)
 UNION ALL SELECT CASE WHEN e.is_reversal THEN'BANK_PAYMENT_REVERSAL'ELSE'BANK_PAYMENT'END,e.source_id,e.source_document_id,e.event_date,e.source_id,e.gst_basis,e.tax_code_id,e.bas_class,NULL::uuid,0::bigint,e.net+e.tax,
 CASE WHEN e.tax<>0 AND e.bas_class<>'EXCLUDED'THEN(e.net+e.tax)*(e.tax-e.recoverable_tax)/e.tax*e.input_taxed_percent/100 ELSE 0 END,
 CASE WHEN e.tax=0 AND e.bas_class<>'EXCLUDED'THEN e.net ELSE 0 END,
 CASE WHEN e.tax<>0 AND e.bas_class<>'EXCLUDED'THEN(e.net+e.tax)*(e.tax-e.recoverable_tax)/e.tax*(1-e.input_taxed_percent/100)ELSE 0 END,false
 FROM accounting.bank_transaction_events e WHERE e.company_id=core.current_company()AND e.kind='PAY'AND e.gst_registered AND e.event_date>=p_from AND e.event_date<p_to
 $$;

CREATE OR REPLACE FUNCTION accounting.bas_purchase_reference(p_from date,p_to date) RETURNS numeric LANGUAGE sql STABLE SET search_path=pg_catalog SET jit=off AS $$
 WITH movements AS MATERIALIZED(SELECT * FROM accounting.report_open_item_movements WHERE company_id=core.current_company() AND side='AP'),
 dated AS MATERIALIZED(SELECT CASE WHEN b.gst_basis='NON_CASH' THEN m.amount ELSE -m.amount END AS amount,
 CASE WHEN b.gst_basis='NON_CASH' AND d.document_type='SUPPLIER_BILL' THEN coalesce(g.attribution_date,b.invoice_date) WHEN b.gst_basis='CASH' THEN coalesce((SELECT min(attribution_date) FROM accounting.purchase_gst_attributions WHERE company_id=m.company_id AND source_document_id=m.source_document_id AND bill_line_id=m.item_line_id),d.business_date) ELSE d.business_date END AS event_date
 FROM movements m JOIN purchase.bill_lines l ON l.company_id=m.company_id AND l.id=m.item_line_id JOIN purchase.bills b ON b.company_id=l.company_id AND b.id=l.bill_id JOIN platform.documents d ON d.company_id=m.company_id AND d.id=m.source_document_id LEFT JOIN accounting.purchase_gst_entries g ON g.company_id=l.company_id AND g.bill_line_id=l.id
 WHERE(b.gst_basis='NON_CASH' AND d.document_type IN('SUPPLIER_BILL','SUPPLIER_CREDIT'))OR(b.gst_basis='CASH' AND d.document_type NOT IN('SUPPLIER_BILL','SUPPLIER_CREDIT')))
 SELECT coalesce(sum(amount),0)+(SELECT coalesce(-sum(l.debit-l.credit),0)FROM(SELECT company_id,id AS source_id,bank_account_id,occurred_on FROM accounting.bank_transactions WHERE kind='PAY'AND gst_registered UNION ALL SELECT h.company_id,v.id,h.bank_account_id,h.occurred_on FROM accounting.bank_transaction_reversals v JOIN accounting.bank_transactions h ON h.company_id=v.company_id AND h.id=v.original_id WHERE h.kind='PAY'AND h.gst_registered)h JOIN accounting.posting_batches b ON b.company_id=h.company_id AND b.source_document_id=h.source_id JOIN accounting.journal_entries j ON j.company_id=b.company_id AND j.posting_batch_id=b.id JOIN accounting.journal_lines l ON l.company_id=j.company_id AND l.journal_entry_id=j.id AND l.account_id=h.bank_account_id WHERE h.company_id=core.current_company()AND h.occurred_on>=p_from AND h.occurred_on<p_to) FROM dated WHERE event_date>=p_from AND event_date<p_to
 $$;

CREATE OR REPLACE FUNCTION accounting.bas_full_summary_raw(p_from date,p_to date,p_method text) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 WITH base AS MATERIALIZED(SELECT accounting.bas_summary(p_from,p_to)AS report),
 sales AS MATERIALIZED(SELECT w AS worksheet,x.*,coalesce(accounting.bank_bas_sales_class(x.source_type,x.source_id,x.tax_code_id),'PENDING')AS classification FROM(VALUES(false),(true))v(w)CROSS JOIN LATERAL accounting.bas_full_sales(p_from,p_to,w)x),
 purchases AS MATERIALIZED(SELECT w AS worksheet,x.* FROM(VALUES(false),(true))v(w)CROSS JOIN LATERAL accounting.bas_full_purchase_items(p_from,p_to,w)x),
 tax AS MATERIALIZED(SELECT * FROM accounting.bas_full_tax_events WHERE company_id=core.current_company() AND attribution_date>=p_from AND attribution_date<p_to),
 sale_totals AS MATERIALIZED(SELECT worksheet,coalesce(sum(gross_amount)FILTER(WHERE classification<>'EXCLUDED'),0)AS g1,coalesce(sum(gross_amount)FILTER(WHERE classification='EXPORT'),0)AS g2,coalesce(sum(gross_amount)FILTER(WHERE classification='OTHER_GST_FREE'),0)AS g3,coalesce(sum(gross_amount)FILTER(WHERE classification='INPUT_TAXED'),0)AS g4,count(*)FILTER(WHERE classification='PENDING')AS errors FROM sales GROUP BY worksheet),
 purchase_totals AS MATERIALIZED(SELECT worksheet,coalesce(sum(gross_amount)FILTER(WHERE purchase_class='CAPITAL'),0)AS g10,coalesce(sum(gross_amount)FILTER(WHERE purchase_class='NON_CAPITAL'),0)AS g11,coalesce(sum(g13)FILTER(WHERE purchase_class IN('CAPITAL','NON_CAPITAL')),0)AS g13,coalesce(sum(g14)FILTER(WHERE purchase_class IN('CAPITAL','NON_CAPITAL')),0)AS g14,coalesce(sum(g15)FILTER(WHERE purchase_class IN('CAPITAL','NON_CAPITAL')),0)AS g15,count(*)FILTER(WHERE issue)AS errors FROM purchases GROUP BY worksheet),
 totals AS MATERIALIZED(SELECT w AS worksheet,coalesce(s.g1,0)AS g1,coalesce(s.g2,0)AS g2,coalesce(s.g3,0)AS g3,coalesce(s.g4,0)AS g4,coalesce(p.g10,0)AS g10,coalesce(p.g11,0)AS g11,coalesce(p.g13,0)AS g13,coalesce(p.g14,0)AS g14,coalesce(p.g15,0)AS g15,coalesce(s.errors,0)+coalesce(p.errors,0)AS errors FROM(VALUES(false),(true))v(w)LEFT JOIN sale_totals s ON s.worksheet=w LEFT JOIN purchase_totals p ON p.worksheet=w),
 purchase_control AS(SELECT accounting.bas_purchase_reference(p_from,p_to)AS expected,coalesce((SELECT sum(gross_amount) FROM purchases WHERE NOT worksheet),0)AS actual,coalesce((SELECT sum(gross_amount) FROM purchases WHERE NOT worksheet AND purchase_class='EXCLUDED'),0)AS excluded),
 tax_totals AS(SELECT coalesce(sum(CASE WHEN side='SALES' THEN gst_amount ELSE -gst_amount END)FILTER(WHERE legal_adjustment),0)AS adjustment_net,coalesce(sum(gst_amount)FILTER(WHERE side='SALES' AND NOT legal_adjustment),0)AS base_sales_tax,coalesce(sum(gst_amount)FILTER(WHERE side='PURCHASES' AND NOT legal_adjustment),0)AS base_purchase_tax FROM tax),
 computed AS(SELECT t.*,g2+g3+g4 AS g5,g1-g2-g3-g4 AS g6,g10+g11 AS g12,g13+g14+g15 AS g16,g10+g11-g13-g14-g15 AS g17,greatest(adjustment_net,0)*11 AS g7,greatest(-adjustment_net,0)*11 AS g18,x.* FROM totals t CROSS JOIN tax_totals x WHERE worksheet),
 sheet AS MATERIALIZED(SELECT *,g6+g7 AS g8,round((g6+g7)/11,2)AS g9,g17+g18 AS g19,round((g17+g18)/11,2)AS g20,round(g6/11,2)-base_sales_tax AS sales_difference,round(g17/11,2)-base_purchase_tax AS purchase_difference FROM computed),
 assessed AS(SELECT b.report,a.*,w.g9,w.g20,w.sales_difference,w.purchase_difference,w.errors AS sheet_errors,pc.expected AS purchase_reference_gross,pc.actual AS purchase_sources_gross,pc.excluded AS excluded_purchase_gross,
 (CASE WHEN b.report->>'status'='UNRECONCILED' OR pc.actual<>pc.expected OR a.g1<>(b.report->'financial'->>'G1')::numeric THEN 'UNRECONCILED' WHEN a.errors+w.errors>0 THEN 'INCOMPLETE' WHEN (p_method='WORKSHEET' AND(abs(w.sales_difference)>0.01 OR abs(w.purchase_difference)>0.01 OR w.g1<0 OR w.g2<0 OR w.g3<0 OR w.g10<0 OR w.g11<0 OR w.g9<0 OR w.g20<0)) OR(p_method='ACCOUNTS' AND(b.report->>'status'='REVIEW_REQUIRED' OR a.g2<0 OR a.g3<0 OR a.g10<0 OR a.g11<0)) THEN 'REVIEW_REQUIRED' ELSE 'READY' END)AS full_status
 FROM base b CROSS JOIN totals a CROSS JOIN sheet w CROSS JOIN purchase_control pc WHERE NOT a.worksheet),
 worksheet_json AS(SELECT jsonb_build_object('G1',g1::text,'G2',g2::text,'G3',g3::text,'G4',g4::text,'G5',g5::text,'G6',g6::text,'G7',g7::text,'G8',g8::text,'G9',g9::text,'G10',g10::text,'G11',g11::text,'G12',g12::text,'G13',g13::text,'G14',g14::text,'G15',g15::text,'G16',g16::text,'G17',g17::text,'G18',g18::text,'G19',g19::text,'G20',g20::text,'adjustmentNetGst',adjustment_net::text,'baseSalesGst',base_sales_tax::text,'basePurchaseGst',base_purchase_tax::text,'salesCalculationDifference',sales_difference::text,'purchaseCalculationDifference',purchase_difference::text,'netCalculationDifference',(g9-g20-(base_sales_tax-base_purchase_tax+adjustment_net))::text,'status',CASE WHEN errors>0 THEN 'INCOMPLETE' WHEN abs(sales_difference)>0.01 OR abs(purchase_difference)>0.01 OR least(g1,g2,g3,g10,g11,g9,g20)<0 THEN 'REVIEW_REQUIRED' ELSE 'READY' END)AS value FROM sheet)
 SELECT a.report||jsonb_build_object('method','FULL_'||p_method,'reportingMethod','FULL','calculationMethod',p_method,'status',a.full_status,
 'financial',(a.report->'financial')||jsonb_build_object('full',jsonb_build_object('G1',CASE WHEN p_method='WORKSHEET' THEN w.value->>'G1' ELSE a.g1::text END,'G2',CASE WHEN p_method='WORKSHEET' THEN w.value->>'G2' ELSE a.g2::text END,'G3',CASE WHEN p_method='WORKSHEET' THEN w.value->>'G3' ELSE a.g3::text END,'G4',CASE WHEN p_method='WORKSHEET' THEN w.value->>'G4' ELSE a.g4::text END,'G10',CASE WHEN p_method='WORKSHEET' THEN w.value->>'G10' ELSE a.g10::text END,'G11',CASE WHEN p_method='WORKSHEET' THEN w.value->>'G11' ELSE a.g11::text END,'1A',CASE WHEN p_method='WORKSHEET' THEN a.g9::text ELSE a.report->'financial'->>'1A' END,'1B',CASE WHEN p_method='WORKSHEET' THEN a.g20::text ELSE a.report->'financial'->>'1B' END,'netGst',CASE WHEN p_method='WORKSHEET' THEN(a.g9-a.g20)::text ELSE a.report->'financial'->>'netGst' END,'classificationIssueCount',a.errors+a.sheet_errors,'purchaseReferenceGross',a.purchase_reference_gross::text,'purchaseSourcesGross',a.purchase_sources_gross::text,'excludedPurchaseGross',a.excluded_purchase_gross::text,'purchaseGrossDifference',(a.purchase_sources_gross-a.purchase_reference_gross)::text,'salesGrossDifference',(a.g1-(a.report->'financial'->>'G1')::numeric)::text,'worksheet',w.value)),
 'wholeDollarLabels',(SELECT jsonb_object_agg(key,trunc(value::numeric)::text) FROM jsonb_each_text(jsonb_build_object('G1',CASE WHEN p_method='WORKSHEET' THEN w.value->>'G1' ELSE a.g1::text END,'G2',CASE WHEN p_method='WORKSHEET' THEN w.value->>'G2' ELSE a.g2::text END,'G3',CASE WHEN p_method='WORKSHEET' THEN w.value->>'G3' ELSE a.g3::text END,'G10',CASE WHEN p_method='WORKSHEET' THEN w.value->>'G10' ELSE a.g10::text END,'G11',CASE WHEN p_method='WORKSHEET' THEN w.value->>'G11' ELSE a.g11::text END,'1A',CASE WHEN p_method='WORKSHEET' THEN a.g9::text ELSE a.report->'financial'->>'1A' END,'1B',CASE WHEN p_method='WORKSHEET' THEN a.g20::text ELSE a.report->'financial'->>'1B' END))),
 'worksheet',w.value,'classificationIssues',coalesce((SELECT jsonb_agg(row ORDER BY source_type,source_id) FROM(SELECT source_type,source_id,jsonb_build_object('side','SALES','sourceType',source_type,'sourceId',source_id,'sourceDocumentId',source_document_id,'taxCodeId',tax_code_id,'classification',classification)AS row FROM sales WHERE classification='PENDING' AND NOT worksheet UNION ALL SELECT source_type,source_id,jsonb_build_object('side','PURCHASES','sourceType',source_type,'sourceId',source_id,'sourceDocumentId',source_document_id,'billLineId',bill_line_id,'classification',purchase_class)FROM purchases WHERE issue AND NOT worksheet)x),'[]'::jsonb))FROM assessed a CROSS JOIN worksheet_json w
 $$;

CREATE OR REPLACE FUNCTION accounting.bas_report_sources(p_from date,p_to date,p_reporting text,p_calculation text) RETURNS TABLE(source_type text,source_id uuid,payload jsonb)LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT * FROM accounting.bas_source_items(p_from,p_to)
 UNION ALL SELECT 'FULL_SALES_'||CASE WHEN w THEN 'WORKSHEET_' ELSE 'ACCOUNTS_' END||x.source_type,x.source_id,to_jsonb(x)||jsonb_build_object('gross_amount',x.gross_amount::text,'sales_class',accounting.bank_bas_sales_class(x.source_type,x.source_id,x.tax_code_id),'classification_id',CASE WHEN x.source_type IN('BANK_RECEIVE','BANK_RECEIVE_REVERSAL')THEN NULL::uuid ELSE(SELECT id FROM accounting.bas_latest_classifications WHERE company_id=x.company_id AND target_kind='TAX_CODE' AND target_id=x.tax_code_id)END,'classification_revision',CASE WHEN x.source_type IN('BANK_RECEIVE','BANK_RECEIVE_REVERSAL')THEN 0 ELSE coalesce((SELECT revision FROM accounting.bas_latest_classifications WHERE company_id=x.company_id AND target_kind='TAX_CODE' AND target_id=x.tax_code_id),0)END,'worksheet',w)FROM(VALUES(false),(true))v(w)CROSS JOIN LATERAL accounting.bas_full_sales(p_from,p_to,w)x WHERE p_reporting='FULL'
 UNION ALL SELECT 'FULL_PURCHASE_'||CASE WHEN w THEN 'WORKSHEET_' ELSE 'ACCOUNTS_' END||x.source_type,x.source_id,to_jsonb(x)||jsonb_build_object('gross_amount',x.gross_amount::text,'g13',x.g13::text,'g14',x.g14::text,'g15',x.g15::text,'worksheet',w)FROM(VALUES(false),(true))v(w)CROSS JOIN LATERAL accounting.bas_full_purchase_items(p_from,p_to,w)x WHERE p_reporting='FULL'
 UNION ALL SELECT CASE WHEN e.is_reversal THEN'BANK_SOURCE_REVERSAL'ELSE'BANK_SOURCE'END,e.source_id,to_jsonb(e)||jsonb_build_object('net',e.net::text,'tax',e.tax::text,'recoverable_tax',e.recoverable_tax::text,'input_taxed_percent',e.input_taxed_percent::text)FROM accounting.bank_transaction_events e WHERE e.company_id=core.current_company()AND e.event_date>=p_from AND e.event_date<p_to
 $$;

CREATE OR REPLACE VIEW accounting.cash_flow_lines WITH(security_invoker=true)AS
 SELECT l.company_id,l.id,l.account_id AS bank_account_id,l.journal_entry_id,l.debit-l.credit AS signed_amount,abs(l.debit-l.credit) AS amount,j.posting_date,j.description,b.source_document_id,b.posting_kind,d.number AS source_number,
 coalesce(rr.receipt_id,pr.payment_id,cr.refund_id,sr.refund_id,gr.original_id) AS original_document_id,
 (rr.id IS NOT NULL OR pr.id IS NOT NULL OR cr.id IS NOT NULL OR sr.id IS NOT NULL OR gr.id IS NOT NULL) AS is_reversal,
 ((b.posting_kind='CUSTOMER_RECEIPT' AND EXISTS(SELECT 1 FROM accounting.customer_receipts r WHERE r.company_id=l.company_id AND r.id=b.source_document_id AND r.bank_account_id=l.account_id)) OR
 (b.posting_kind='SUPPLIER_PAYMENT' AND EXISTS(SELECT 1 FROM accounting.supplier_payments p WHERE p.company_id=l.company_id AND p.id=b.source_document_id AND p.bank_account_id=l.account_id)) OR
 (b.posting_kind='CUSTOMER_REFUND' AND EXISTS(SELECT 1 FROM accounting.customer_refunds f WHERE f.company_id=l.company_id AND f.id=b.source_document_id)) OR
 (b.posting_kind='SUPPLIER_REFUND' AND EXISTS(SELECT 1 FROM accounting.supplier_refunds f WHERE f.company_id=l.company_id AND f.id=b.source_document_id AND f.bank_account_id=l.account_id))) AS trade_source,
 NOT EXISTS(SELECT 1 FROM accounting.journal_lines other LEFT JOIN accounting.cash_flow_scopes sc ON sc.company_id=other.company_id AND sc.bank_account_id=other.account_id WHERE other.company_id=l.company_id AND other.journal_entry_id=j.id AND(other.debit<>0 OR other.credit<>0)AND coalesce(sc.included,false)=false) AS pure_transfer
 FROM accounting.journal_lines l JOIN accounting.cash_flow_scopes s ON s.company_id=l.company_id AND s.bank_account_id=l.account_id AND s.included JOIN accounting.journal_entries j ON j.company_id=l.company_id AND j.id=l.journal_entry_id JOIN accounting.posting_batches b ON b.company_id=j.company_id AND b.id=j.posting_batch_id JOIN platform.documents d ON d.company_id=b.company_id AND d.id=b.source_document_id
 LEFT JOIN accounting.receipt_reversals rr ON rr.company_id=b.company_id AND rr.id=b.source_document_id AND b.posting_kind='RECEIPT_REVERSAL'
 LEFT JOIN accounting.supplier_payment_reversals pr ON pr.company_id=b.company_id AND pr.id=b.source_document_id AND b.posting_kind='SUPPLIER_PAYMENT_REVERSAL'
 LEFT JOIN accounting.customer_refund_reversals cr ON cr.company_id=b.company_id AND cr.id=b.source_document_id AND b.posting_kind='CUSTOMER_REFUND_REVERSAL'
 LEFT JOIN accounting.supplier_refund_reversals sr ON sr.company_id=b.company_id AND sr.id=b.source_document_id AND b.posting_kind='SUPPLIER_REFUND_REVERSAL' LEFT JOIN accounting.bank_transaction_reversals gr ON gr.company_id=b.company_id AND gr.id=b.source_document_id WHERE l.debit<>l.credit;

CREATE OR REPLACE FUNCTION accounting.period_preflight(p_id uuid,p_bas_na boolean DEFAULT false)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog SET jit=off AS $$
 DECLARE c uuid:=core.current_company();p accounting.periods;y accounting.fiscal_years;f jsonb;issues jsonb:='[]';live jsonb;bas jsonb;covered int;required boolean;activity boolean;bad int;today date;BEGIN
 PERFORM accounting.require_close_access('accounting.periods.read');SELECT*INTO p FROM accounting.periods WHERE company_id=c AND id=p_id;IF NOT FOUND THEN RAISE EXCEPTION 'Accounting period unavailable' USING ERRCODE='HT404';END IF;SELECT*INTO y FROM accounting.fiscal_years WHERE company_id=c AND id=p.fiscal_year_id;
 SELECT (now()AT TIME ZONE timezone)::date,gst_registered INTO today,required FROM core.companies WHERE id=c;
 IF p.ends_on>today THEN issues:=issues||jsonb_build_array('PERIOD_NOT_ENDED');END IF;
 IF p.starts_on<y.starts_on OR p.ends_on>y.ends_on OR EXISTS(SELECT 1 FROM accounting.periods q WHERE q.company_id=c AND q.id<>p.id AND q.starts_on<p.ends_on AND q.ends_on>p.starts_on)THEN issues:=issues||jsonb_build_array('INVALID_ACCOUNTING_CALENDAR');END IF;
 IF EXISTS(SELECT 1 FROM accounting.periods WHERE company_id=c AND starts_on<p.starts_on AND state<>'CLOSED')THEN issues:=issues||jsonb_build_array('EARLIER_PERIODS_OPEN');END IF;
 IF EXISTS(SELECT 1 FROM accounting.fiscal_year_controls WHERE company_id=c AND id=p.fiscal_year_id AND state='CLOSED')THEN issues:=issues||jsonb_build_array('FISCAL_YEAR_CLOSED');END IF;
 f:=accounting.close_financials(p.starts_on,p.ends_on);
 SELECT coalesce(jsonb_agg(jsonb_build_object('code',check_code,'entityId',entity_id,'expected',expected::text,'actual',actual::text,'unit',unit)ORDER BY check_code,entity_id),'[]'::jsonb)INTO live FROM accounting.reconciliation_checks()WHERE expected IS DISTINCT FROM actual;
 IF jsonb_array_length(live)>0 THEN issues:=issues||jsonb_build_array('CURRENT_SUBLEDGER_INCONSISTENT');END IF;
 IF(f->>'inventoryDifference')::numeric<>0 OR(f->>'settlementErrorCount')::int>0 OR(f->>'trialBalanceDifference')::numeric<>0 OR(f->'gst'->>'glErrorCount')::int+(f->'gst'->>'roleErrorCount')::int+(f->'gst'->>'missingAccountCount')::int>0 OR(f->'gst'->>'labelDifference')::numeric<>0 THEN issues:=issues||jsonb_build_array('HISTORICAL_LEDGERS_UNRECONCILED');END IF;
 SELECT coalesce(sum(least(b.to_date,p.ends_on)-greatest(b.from_date,p.starts_on)),0),coalesce(jsonb_agg(jsonb_build_object('id',b.id,'from',b.from_date,'to',b.to_date,'state',k.state,'reportingMethod',b.reporting_method,'calculationMethod',b.calculation_method,'snapshotId',k.current_snapshot_id)ORDER BY b.from_date),'[]'::jsonb),count(*)FILTER(WHERE b.to_date<=p.ends_on AND k.state='OPEN')INTO covered,bas,bad FROM accounting.bas_effective_periods b JOIN accounting.bas_period_controls k ON k.company_id=b.company_id AND k.id=b.id WHERE b.company_id=c AND b.from_date<p.ends_on AND b.to_date>p.starts_on;
 SELECT EXISTS(SELECT 1 FROM accounting.bas_tax_events WHERE company_id=c AND attribution_date>=p.starts_on AND attribution_date<p.ends_on AND gst_amount<>0)OR EXISTS(SELECT 1 FROM accounting.bas_turnover(p.starts_on,p.ends_on)WHERE gross_amount<>0)OR EXISTS(SELECT 1 FROM purchase.bill_lines l JOIN purchase.bills b ON b.company_id=l.company_id AND b.id=l.bill_id JOIN platform.documents d ON d.company_id=b.company_id AND d.id=b.id WHERE l.company_id=c AND((b.invoice_date>=p.starts_on AND b.invoice_date<p.ends_on)OR(d.business_date>=p.starts_on AND d.business_date<p.ends_on))AND(l.snapshot->>'gstRegistered')::boolean) INTO activity;
 activity:=activity OR EXISTS(SELECT 1 FROM accounting.bank_transactions h JOIN accounting.bank_transaction_lines l ON l.company_id=h.company_id AND l.transaction_id=h.id WHERE h.company_id=c AND h.kind='PAY'AND h.gst_registered AND h.occurred_on>=p.starts_on AND h.occurred_on<p.ends_on AND l.bas_class<>'EXCLUDED');required:=required OR activity OR covered>0;
 IF p_bas_na THEN IF activity OR covered>0 THEN issues:=issues||jsonb_build_array('BAS_NOT_APPLICABLE_CONTRADICTS_SOURCES');END IF;ELSE IF required AND covered<>p.ends_on-p.starts_on THEN issues:=issues||jsonb_build_array('BAS_COVERAGE_MISSING');END IF;END IF;
 IF bad>0 THEN issues:=issues||jsonb_build_array('ENDED_BAS_PERIOD_NOT_FINALIZED');END IF;
 IF EXISTS(SELECT 1 FROM accounting.bas_effective_periods b JOIN accounting.bas_period_controls k ON k.company_id=b.company_id AND k.id=b.id JOIN accounting.bas_snapshots bs ON bs.company_id=k.company_id AND bs.id=k.current_snapshot_id WHERE b.company_id=c AND b.from_date<p.ends_on AND b.to_date>p.starts_on AND k.state IN('FINALIZED','LODGED')AND accounting.bas_financial_hash(accounting.bas_report(b.from_date,b.to_date,b.reporting_method,b.calculation_method))<>bs.financial_hash)THEN issues:=issues||jsonb_build_array('BAS_SNAPSHOT_DRIFT');END IF;
 RETURN jsonb_build_object('companyId',c,'periodId',p.id,'fiscalYearId',p.fiscal_year_id,'from',p.starts_on,'to',p.ends_on,'state',p.state,'version',p.version,'legacyUncertified',p.state='CLOSED'AND p.current_close_snapshot_id IS NULL,'basNotApplicableConfirmed',p_bas_na,'basRequired',required,'basPeriods',bas,'status',CASE WHEN jsonb_array_length(issues)=0 THEN'READY'ELSE'BLOCKED'END,'issues',issues,'currentMismatches',live,'financial',f,'yearEndBridge',accounting.year_closing_bridge(p.ends_on),'snapshotAt',statement_timestamp());END $$;

CREATE VIEW accounting.bank_transaction_gl_differences WITH(security_invoker=true)AS
 WITH sources AS(SELECT company_id,id AS source_id,id AS original_id,journal_entry_id,false AS reversed FROM accounting.bank_transactions UNION ALL SELECT company_id,id,original_id,journal_entry_id,true FROM accounting.bank_transaction_reversals),expected AS(SELECT s.company_id,s.source_id,p.account_id,sum(CASE WHEN s.reversed THEN p.credit ELSE p.debit END)AS debit,sum(CASE WHEN s.reversed THEN p.debit ELSE p.credit END)AS credit FROM sources s JOIN accounting.bank_transaction_plan p ON p.company_id=s.company_id AND p.source_document_id=s.original_id GROUP BY s.company_id,s.source_id,p.account_id),actual AS(SELECT s.company_id,s.source_id,l.account_id,sum(l.debit)AS debit,sum(l.credit)AS credit FROM sources s JOIN accounting.journal_lines l ON l.company_id=s.company_id AND l.journal_entry_id=s.journal_entry_id GROUP BY s.company_id,s.source_id,l.account_id)
 SELECT coalesce(e.company_id,a.company_id)AS company_id,coalesce(e.source_id,a.source_id)AS source_id,sum(abs(coalesce(e.debit,0)-coalesce(a.debit,0))+abs(coalesce(e.credit,0)-coalesce(a.credit,0)))AS difference FROM expected e FULL JOIN actual a USING(company_id,source_id,account_id)GROUP BY coalesce(e.company_id,a.company_id),coalesce(e.source_id,a.source_id);

CREATE OR REPLACE FUNCTION accounting.reconciliation_checks()
RETURNS TABLE(check_code text,entity_id uuid,expected numeric,actual numeric,unit text)
LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
 PERFORM accounting.require_reconciliation_access();
 RETURN QUERY
 WITH
 stock_deltas AS (
  SELECT b.id AS balance_id,o.quantity AS qty,0::numeric AS val
  FROM inventory.stock_openings o JOIN inventory.stock_balances b ON b.company_id=o.company_id AND b.warehouse_id=o.warehouse_id AND b.product_id=o.product_id WHERE o.company_id=core.current_company()
  UNION ALL SELECT stock_balance_id,0,value FROM inventory.valuation_openings WHERE company_id=core.current_company()
  UNION ALL SELECT stock_balance_id,base_quantity,valuation_amount FROM purchase.receipt_lines WHERE company_id=core.current_company() AND stock_balance_id IS NOT NULL
  UNION ALL SELECT stock_balance_id,-quantity,-cost FROM inventory.stock_movements WHERE company_id=core.current_company()
  UNION ALL SELECT b.id,l.base_quantity,l.cost FROM inventory.sales_return_lines l JOIN inventory.sales_returns r ON r.company_id=l.company_id AND r.id=l.return_id JOIN sales.order_lines ol ON ol.company_id=l.company_id AND ol.id=l.order_line_id JOIN inventory.stock_balances b ON b.company_id=r.company_id AND b.warehouse_id=r.warehouse_id AND b.product_id=ol.product_id WHERE l.company_id=core.current_company()
  UNION ALL SELECT stock_balance_id,-base_quantity,-cost FROM purchase.return_lines WHERE company_id=core.current_company() AND stock_balance_id IS NOT NULL
  UNION ALL SELECT stock_balance_id,quantity_delta,value_delta FROM inventory.operation_lines WHERE company_id=core.current_company()
  UNION ALL SELECT stock_balance_id,-quantity,-cost FROM inventory.transit_transfer_lines WHERE company_id=core.current_company()
  UNION ALL SELECT stock_balance_id,quantity,cost FROM inventory.transit_event_lines WHERE company_id=core.current_company() AND stock_balance_id IS NOT NULL
 UNION ALL SELECT stock_balance_id,0,inventory_delta FROM inventory.purchase_value_adjustments WHERE company_id=core.current_company() AND stock_balance_id IS NOT NULL
 ), stock_totals AS (SELECT balance_id,sum(qty) AS qty,sum(val) AS val FROM stock_deltas GROUP BY balance_id),
 stock AS (
  SELECT b.*,v.value,coalesce(t.qty,0) AS ledger_qty,coalesce(t.val,0) AS ledger_val,
   coalesce((SELECT sum(r.remaining_quantity) FROM inventory.stock_reservations r WHERE r.company_id=b.company_id AND r.stock_balance_id=b.id),0) AS ledger_reserved
  FROM inventory.stock_balances b LEFT JOIN inventory.stock_values v ON v.company_id=b.company_id AND v.stock_balance_id=b.id LEFT JOIN stock_totals t ON t.balance_id=b.id WHERE b.company_id=core.current_company()
 ), gl AS (
  SELECT a.id,a.control_kind,l.party_id,sum(l.debit-l.credit) AS balance
  FROM accounting.journal_lines l JOIN accounting.accounts a ON a.company_id=l.company_id AND a.id=l.account_id WHERE l.company_id=core.current_company() GROUP BY a.id,a.control_kind,l.party_id
 ), ar_lines AS (SELECT id,customer_id,party_id,remaining_gross-net_paid_amount AS balance FROM sales.invoice_line_balances WHERE company_id=core.current_company()
 ), ar_customer AS (SELECT customer_id,sum(balance) AS balance FROM ar_lines GROUP BY customer_id),
 ar_party AS (SELECT party_id,sum(balance) AS balance FROM ar_lines GROUP BY party_id),
 customer_advances AS (
  SELECT a.id,r.customer_id,a.advance_account_id,a.clearing_account_id,a.amount
   -coalesce((SELECT sum(ap.amount) FROM accounting.active_advance_applications ap WHERE ap.company_id=a.company_id AND ap.advance_id=a.id),0)
   -coalesce((SELECT sum(f.amount) FROM accounting.active_customer_refunds f WHERE f.company_id=a.company_id AND f.advance_id=a.id),0) AS balance
  FROM accounting.active_customer_advances a JOIN accounting.active_customer_receipts r ON r.company_id=a.company_id AND r.id=a.receipt_id WHERE a.company_id=core.current_company()
 ), unbilled AS (SELECT customer_id,sum(amount-released_amount) AS balance FROM sales.credit_commitments WHERE company_id=core.current_company() GROUP BY customer_id),
 ap_party AS (SELECT party_id,sum(outstanding_amount-available_credit) AS balance FROM accounting.ap_balances WHERE company_id=core.current_company() GROUP BY party_id),
 transit_accounts AS (
  SELECT transit_account_id AS id FROM inventory.transit_transfers WHERE company_id=core.current_company() AND transit_account_id IS NOT NULL
  UNION SELECT account_id FROM accounting.account_mappings WHERE company_id=core.current_company() AND purpose='INVENTORY_TRANSIT'
 ), advance_accounts AS (
  SELECT advance_account_id AS id FROM customer_advances
  UNION SELECT account_id FROM accounting.account_mappings WHERE company_id=core.current_company() AND purpose='CUSTOMER_ADVANCES'
 ), supplier_advance_accounts AS (
  SELECT account_id AS id FROM accounting.supplier_advances WHERE company_id=core.current_company()
  UNION SELECT account_id FROM accounting.account_mappings WHERE company_id=core.current_company() AND purpose='SUPPLIER_ADVANCES'
 ), return_accounts AS (
  SELECT contra_account_id AS id FROM purchase.return_lines WHERE company_id=core.current_company() AND bill_line_id IS NOT NULL AND contra_account_id IS NOT NULL
  UNION SELECT account_id FROM accounting.account_mappings WHERE company_id=core.current_company() AND purpose='PURCHASE_RETURN_CLEARING'
 ), grni_party AS (
  SELECT g.party_id,sum(g.amount
   -coalesce((SELECT sum(b.grni_amount) FROM purchase.bill_lines b WHERE b.company_id=g.company_id AND b.grni_item_id=g.id),0)
   -coalesce((SELECT sum(r.valuation_amount) FROM purchase.return_lines r WHERE r.company_id=g.company_id AND r.receipt_line_id=g.receipt_line_id AND r.bill_line_id IS NULL),0)) AS balance
  FROM accounting.grni_items g WHERE g.company_id=core.current_company() GROUP BY g.party_id
 ), checks AS (
  SELECT 'stock.quantity'::text AS code,s.id AS entity,s.ledger_qty AS e,s.on_hand AS a,'BASE_QUANTITY'::text AS u FROM stock s
  UNION ALL SELECT 'stock.value',s.id,s.ledger_val,coalesce(s.value,0),'AUD' FROM stock s
  UNION ALL SELECT 'stock.valuation_missing',s.id,1,CASE WHEN s.value IS NULL THEN 0 ELSE 1 END,'COUNT' FROM stock s WHERE s.on_hand>0
  UNION ALL SELECT 'stock.reserved',s.id,s.ledger_reserved,s.reserved,'BASE_QUANTITY' FROM stock s
  UNION ALL SELECT 'reservation.consumed',r.id,coalesce((SELECT sum(m.quantity) FROM inventory.stock_movements m JOIN inventory.pick_lines pl ON pl.company_id=m.company_id AND pl.id=m.pick_line_id WHERE pl.company_id=r.company_id AND pl.order_line_id=r.order_line_id),0),r.consumed_quantity,'BASE_QUANTITY' FROM inventory.stock_reservations r WHERE r.company_id=core.current_company()
  UNION ALL SELECT 'credit.receivable',c.id,coalesce(a.balance,0),coalesce(x.receivable,0),'AUD' FROM crm.customers c LEFT JOIN ar_customer a ON a.customer_id=c.id LEFT JOIN crm.customer_credit_exposures x ON x.company_id=c.company_id AND x.customer_id=c.id WHERE c.company_id=core.current_company()
  UNION ALL SELECT 'credit.unbilled',c.id,coalesce(b.balance,0),coalesce(x.unbilled_orders,0),'AUD' FROM crm.customers c LEFT JOIN unbilled b ON b.customer_id=c.id LEFT JOIN crm.customer_credit_exposures x ON x.company_id=c.company_id AND x.customer_id=c.id WHERE c.company_id=core.current_company()
  UNION ALL SELECT 'credit.advances',c.id,coalesce((SELECT sum(balance) FROM customer_advances ad WHERE ad.customer_id=c.id),0),coalesce(x.available_advances,0),'AUD' FROM crm.customers c LEFT JOIN crm.customer_credit_exposures x ON x.company_id=c.company_id AND x.customer_id=c.id WHERE c.company_id=core.current_company()
  UNION ALL SELECT 'credit.projection_missing',c.id,1,CASE WHEN x.id IS NULL THEN 0 ELSE 1 END,'COUNT' FROM crm.customers c LEFT JOIN crm.customer_credit_exposures x ON x.company_id=c.company_id AND x.customer_id=c.id WHERE c.company_id=core.current_company()
  UNION ALL SELECT 'credit.commitment',co.id,CASE WHEN d.state='CANCELLED' THEN 0 ELSE o.gross-coalesce((SELECT sum(i.gross) FROM sales.invoices i WHERE i.company_id=co.company_id AND i.order_id=o.id),0)-coalesce((SELECT sum(r.cancelled_gross) FROM inventory.sales_return_lines r JOIN sales.order_lines ol ON ol.company_id=r.company_id AND ol.id=r.order_line_id WHERE ol.company_id=co.company_id AND ol.order_id=o.id AND r.invoice_line_id IS NULL),0) END,co.amount-co.released_amount,'AUD' FROM sales.credit_commitments co JOIN sales.orders o ON o.company_id=co.company_id AND o.id=co.order_id JOIN platform.documents d ON d.company_id=o.company_id AND d.id=o.id WHERE co.company_id=core.current_company()
  UNION ALL SELECT 'invoice.lines',i.id,i.gross,coalesce((SELECT sum(l.gross) FROM sales.invoice_lines l WHERE l.company_id=i.company_id AND l.invoice_id=i.id),0),'AUD' FROM sales.invoices i WHERE i.company_id=core.current_company()
  UNION ALL SELECT 'invoice.receivable',i.id,i.gross,coalesce(r.amount,0),'AUD' FROM sales.invoices i LEFT JOIN accounting.receivable_items r ON r.company_id=i.company_id AND r.invoice_id=i.id WHERE i.company_id=core.current_company()
  UNION ALL SELECT 'invoice.receivable_missing',i.id,1,CASE WHEN r.id IS NULL THEN 0 ELSE 1 END,'COUNT' FROM sales.invoices i LEFT JOIN accounting.receivable_items r ON r.company_id=i.company_id AND r.invoice_id=i.id WHERE i.company_id=core.current_company()
  UNION ALL SELECT 'bill.lines',b.id,b.gross,coalesce((SELECT sum(l.net+l.tax) FROM purchase.bill_lines l WHERE l.company_id=b.company_id AND l.bill_id=b.id),0),'AUD' FROM purchase.bills b WHERE b.company_id=core.current_company()
  UNION ALL SELECT 'bill.payable',b.id,b.gross,coalesce(a.amount,0),'AUD' FROM purchase.bills b LEFT JOIN accounting.ap_items a ON a.company_id=b.company_id AND a.bill_id=b.id WHERE b.company_id=core.current_company()
  UNION ALL SELECT 'bill.payable_missing',b.id,1,CASE WHEN a.id IS NULL THEN 0 ELSE 1 END,'COUNT' FROM purchase.bills b LEFT JOIN accounting.ap_items a ON a.company_id=b.company_id AND a.bill_id=b.id WHERE b.company_id=core.current_company()
  UNION ALL SELECT 'gl.inventory',core.current_company(),coalesce((SELECT sum(value) FROM stock),0)+coalesce((SELECT sum(remaining_cost) FROM inventory.transit_line_balances WHERE company_id=core.current_company()),0),coalesce((SELECT sum(balance) FROM gl WHERE control_kind='INVENTORY'),0),'AUD'
  UNION ALL SELECT 'gl.transit',ta.id,coalesce((SELECT sum(b.remaining_cost) FROM inventory.transit_line_balances b JOIN inventory.transit_transfers t ON t.company_id=b.company_id AND t.id=b.transfer_id WHERE b.company_id=core.current_company() AND t.transit_account_id=ta.id),0),coalesce((SELECT sum(balance) FROM gl WHERE id=ta.id),0),'AUD' FROM transit_accounts ta
  UNION ALL SELECT 'gl.receivable',p.id,coalesce(a.balance,0),coalesce((SELECT sum(balance) FROM gl WHERE control_kind='AR' AND party_id=p.id),0),'AUD' FROM crm.parties p LEFT JOIN ar_party a ON a.party_id=p.id WHERE p.company_id=core.current_company()
  UNION ALL SELECT 'gl.receivable_unassigned',core.current_company(),0,coalesce((SELECT sum(balance) FROM gl WHERE control_kind='AR' AND party_id IS NULL),0),'AUD'
  UNION ALL SELECT 'gl.payable',p.id,coalesce(a.balance,0),-coalesce((SELECT sum(balance) FROM gl WHERE control_kind='AP' AND party_id=p.id),0),'AUD' FROM crm.parties p LEFT JOIN ap_party a ON a.party_id=p.id WHERE p.company_id=core.current_company()
  UNION ALL SELECT 'gl.payable_unassigned',core.current_company(),0,coalesce((SELECT sum(balance) FROM gl WHERE control_kind='AP' AND party_id IS NULL),0),'AUD'
  UNION ALL SELECT 'gl.grni',p.id,coalesce(g.balance,0),-coalesce((SELECT sum(balance) FROM gl WHERE control_kind='GRNI' AND party_id=p.id),0),'AUD' FROM crm.parties p LEFT JOIN grni_party g ON g.party_id=p.id WHERE p.company_id=core.current_company()
  UNION ALL SELECT 'gl.grni_unassigned',core.current_company(),0,coalesce((SELECT sum(balance) FROM gl WHERE control_kind='GRNI' AND party_id IS NULL),0),'AUD'
  UNION ALL SELECT 'gl.customer_advances',aa.id,coalesce((SELECT sum(balance) FROM customer_advances WHERE advance_account_id=aa.id),0),-coalesce((SELECT sum(balance) FROM gl WHERE id=aa.id),0),'AUD' FROM advance_accounts aa
  UNION ALL SELECT 'gl.supplier_advances',aa.id,coalesce((SELECT sum(available) FROM accounting.supplier_advance_balances WHERE company_id=core.current_company() AND account_id=aa.id),0),coalesce((SELECT sum(balance) FROM gl WHERE id=aa.id),0),'AUD' FROM supplier_advance_accounts aa
  UNION ALL SELECT 'gl.purchase_return_clearing',ra.id,coalesce((SELECT sum(r.valuation_amount-coalesce((SELECT sum(cl.net+cl.tax-cl.recoverable_tax+cl.clearing_adjustment) FROM purchase.supplier_credit_lines cl WHERE cl.company_id=r.company_id AND cl.return_line_id=r.id),0)) FROM purchase.return_lines r WHERE r.company_id=core.current_company() AND r.bill_line_id IS NOT NULL AND r.contra_account_id=ra.id),0),coalesce((SELECT sum(balance) FROM gl WHERE id=ra.id),0),'AUD' FROM return_accounts ra
  UNION ALL SELECT 'journal.balance',j.id,0,coalesce(sum(l.debit-l.credit),0),'AUD' FROM accounting.journal_entries j LEFT JOIN accounting.journal_lines l ON l.company_id=j.company_id AND l.journal_entry_id=j.id WHERE j.company_id=core.current_company() GROUP BY j.id
  UNION ALL SELECT 'journal.lines',j.id,1,CASE WHEN count(l.id)>=2 THEN 1 ELSE 0 END,'COUNT' FROM accounting.journal_entries j LEFT JOIN accounting.journal_lines l ON l.company_id=j.company_id AND l.journal_entry_id=j.id WHERE j.company_id=core.current_company() GROUP BY j.id
  UNION ALL SELECT 'journal.batch_entry',b.id,1,count(j.id)::numeric,'COUNT' FROM accounting.posting_batches b LEFT JOIN accounting.journal_entries j ON j.company_id=b.company_id AND j.posting_batch_id=b.id WHERE b.company_id=core.current_company() GROUP BY b.id

  UNION ALL SELECT 'credit_application.total',a.id,a.amount,coalesce((SELECT sum(amount) FROM purchase.credit_application_lines WHERE company_id=a.company_id AND application_id=a.id),0),'AUD' FROM purchase.credit_applications a WHERE a.company_id=core.current_company()
  UNION ALL SELECT 'credit_unapplication.total',u.id,a.amount,u.amount,'AUD' FROM purchase.credit_unapplications u JOIN purchase.credit_applications a ON a.company_id=u.company_id AND a.id=u.application_id WHERE u.company_id=core.current_company()
  UNION ALL SELECT 'credit_application.capacity',cl.id,0,greatest(0,-cl.unallocated_amount),'AUD' FROM purchase.supplier_credit_line_balances cl WHERE cl.company_id=core.current_company()
  UNION ALL SELECT 'credit_application.funds',b.id,0,greatest(0,-b.net_paid_amount),'AUD' FROM purchase.bill_line_balances b WHERE b.company_id=core.current_company() AND EXISTS(SELECT 1 FROM purchase.credit_application_lines l WHERE l.company_id=b.company_id AND b.id IN(l.source_bill_line_id,l.target_bill_line_id))

  UNION ALL SELECT 'customer_credit_application.total',a.id,a.amount,coalesce((SELECT sum(amount) FROM sales.credit_application_lines WHERE company_id=a.company_id AND application_id=a.id),0),'AUD' FROM sales.credit_applications a WHERE a.company_id=core.current_company()
  UNION ALL SELECT 'customer_credit_unapplication.total',u.id,a.amount,u.amount,'AUD' FROM sales.credit_unapplications u JOIN sales.credit_applications a ON a.company_id=u.company_id AND a.id=u.application_id WHERE u.company_id=core.current_company()
  UNION ALL SELECT 'customer_credit_application.capacity',cl.id,0,greatest(0,-cl.unallocated_amount),'AUD' FROM sales.customer_credit_line_balances cl WHERE cl.company_id=core.current_company()
  UNION ALL SELECT 'customer_credit_application.funds',b.id,0,greatest(0,-b.net_paid_amount),'AUD' FROM sales.invoice_line_balances b WHERE b.company_id=core.current_company() AND EXISTS(SELECT 1 FROM sales.credit_application_lines l WHERE l.company_id=b.company_id AND b.id IN(l.source_invoice_line_id,l.target_invoice_line_id))

  UNION ALL SELECT 'receipt_reversal.amount',x.id,r.amount,x.amount,'AUD' FROM accounting.receipt_reversals x JOIN accounting.customer_receipts r ON r.company_id=x.company_id AND r.id=x.receipt_id WHERE x.company_id=core.current_company()
  UNION ALL SELECT 'advance_unapplication.amount',x.id,a.amount,x.amount,'AUD' FROM accounting.advance_unapplications x JOIN accounting.advance_applications a ON a.company_id=x.company_id AND a.id=x.application_id WHERE x.company_id=core.current_company()
  UNION ALL SELECT 'settlement.negative_funds',b.id,0,greatest(0,-b.net_paid_amount),'AUD' FROM sales.invoice_line_balances b WHERE b.company_id=core.current_company()
  UNION ALL SELECT 'advance.negative_available',b.id,0,greatest(0,-b.available),'AUD' FROM accounting.customer_advance_balances b WHERE b.company_id=core.current_company()

  UNION ALL SELECT 'supplier_payment_reversal.amount',r.id,p.amount,r.amount,'AUD' FROM accounting.supplier_payment_reversals r JOIN accounting.supplier_payments p ON p.company_id=r.company_id AND p.id=r.payment_id WHERE r.company_id=core.current_company()
  UNION ALL SELECT 'supplier_advance_unapplication.amount',u.id,a.amount,u.amount,'AUD' FROM accounting.supplier_advance_unapplications u JOIN accounting.supplier_advance_applications a ON a.company_id=u.company_id AND a.id=u.application_id WHERE u.company_id=core.current_company()
  UNION ALL SELECT 'supplier_settlement.negative_funds',b.id,0,greatest(0,-b.net_paid_amount),'AUD' FROM purchase.bill_line_balances b WHERE b.company_id=core.current_company()
  UNION ALL SELECT 'supplier_advance.negative_available',a.id,0,greatest(0,-a.available),'AUD' FROM accounting.supplier_advance_balances a WHERE a.company_id=core.current_company()

  UNION ALL SELECT 'customer_refund_reversal.amount',v.id,r.amount,v.amount,'AUD' FROM accounting.customer_refund_reversals v JOIN accounting.customer_refunds r ON r.company_id=v.company_id AND r.id=v.refund_id WHERE v.company_id=core.current_company()

  UNION ALL SELECT 'supplier_refund_reversal.amount',v.id,r.amount,v.amount,'AUD' FROM accounting.supplier_refund_reversals v JOIN accounting.supplier_refunds r ON r.company_id=v.company_id AND r.id=v.refund_id WHERE v.company_id=core.current_company()

 UNION ALL SELECT 'stock.position_quantity',b.id,b.on_hand,coalesce((SELECT sum(quantity) FROM inventory.positions WHERE company_id=b.company_id AND stock_balance_id=b.id),0),'BASE_QUANTITY' FROM inventory.stock_balances b WHERE b.company_id=core.current_company()
 UNION ALL SELECT 'stock.position_ledger',p.id,p.quantity,coalesce((SELECT sum(quantity) FROM inventory.position_movements WHERE company_id=p.company_id AND position_id=p.id),0),'BASE_QUANTITY' FROM inventory.positions p WHERE p.company_id=core.current_company()
 ) SELECT code,entity,e,a,u FROM checks;
 RETURN QUERY SELECT 'GENERAL_BANK_SOURCE'::text,source_id,0::numeric,difference,'AUD'::text FROM accounting.bank_transaction_gl_differences WHERE company_id=core.current_company();
END $$;

GRANT SELECT ON accounting.bank_transactions,accounting.bank_transaction_lines,accounting.bank_transaction_reversals,accounting.bank_transaction_events,accounting.bank_transaction_plan,accounting.bank_transaction_gl_differences TO htt_app;
REVOKE ALL ON FUNCTION identity.seed_general_banking_roles(uuid),accounting.require_general_banking(text),accounting.validate_general_banking(),accounting.guard_general_banking_document(),accounting.bank_bas_sales_class(text,uuid,uuid),accounting.post_general_banking(text,uuid,uuid,date,text,text,jsonb,numeric,text,boolean,text,date,uuid,bigint),accounting.reverse_general_banking(uuid,bigint,text,text)FROM PUBLIC;
GRANT EXECUTE ON FUNCTION accounting.require_general_banking(text),accounting.bank_bas_sales_class(text,uuid,uuid),accounting.post_general_banking(text,uuid,uuid,date,text,text,jsonb,numeric,text,boolean,text,date,uuid,bigint),accounting.reverse_general_banking(uuid,bigint,text,text)TO htt_app;
CREATE INDEX ON accounting.bank_transactions(company_id,occurred_on,id);
CREATE INDEX ON accounting.bank_transactions(company_id,statement_line_id)WHERE statement_line_id IS NOT NULL;

